/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
/* A41 staging · exact frozen manifest guile–ham (80 lemmas). */
'use strict';
const D=globalThis.RA.D;
const Q=(w,n,s,p,a,b,c,x)=>({id:`${w}.q${n}`,senseId:`${w}.s${s}`,errorType:'meaning',type:'辨义与用法',prompt:p,options:[a,b,c],answer:a,explain:x});
const M=(wrong,right,reason,type='meaning')=>({errorType:type,wrong,right,reason});
const C=(s,domain,en,zh,structure,grammar,rationale)=>({senseId:s,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:`Etymonline, https://www.etymonline.com/word/${w.toLowerCase().replaceAll(' ','-')}`});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:[c],mistakes:[m],quiz:qs});
P('guile','guile 经古法语进入英语，词源更早的来源并不确定；现代义强调用巧妙但不诚实的方式达成目的。',C('guile.s1','政治修辞','The negotiator relied on guile to conceal the true cost until the other side had already signed the agreement.','谈判者用诡计隐瞒真实成本，直到对方已经签署协议。','The negotiator relied on guile / to conceal the true cost / until the other side had already signed / the agreement.','rely on guile 表示依靠狡诈手段；to conceal 说明其目的。','隐瞒成本以操纵对方决定，体现欺骗性的巧计。'),M('The negotiator used guile by stating every cost openly and correcting each misleading claim.','The negotiator used honesty by stating every cost openly and correcting each misleading claim.','坦诚披露信息与 guile 所含的欺骗手段相反。'),[Q('guile',1,1,'Guile is?','clever but dishonest skill used to deceive','a strong gust of wind','a musical instrument','guile 指带有欺骗性的狡诈。'),Q('guile',2,1,'A person acting with guile might?','hide a key fact to gain an advantage','publish every relevant fact','ask for directions politely','隐瞒关键事实以获利体现 guile。'),Q('guile',3,1,'Which is closest in meaning to guile?','deceitful cunning','genuine kindness','physical strength','deceitful cunning 是狡诈。'),Q('guile',4,1,'A story about guile is likely to involve?','a clever trick that misleads someone','a clear weather report','a guitar lesson','guile 常涉及巧妙欺骗。')]);
P('guileless','guileless 由 guile 加 -less 构成，表示没有欺诈心机、诚实坦率。',C('guileless.s2','人际交流','Her guileless question showed exactly what she was thinking, without any attempt to flatter the panel or hide her doubts.','她坦率的问题直接表明了自己的想法，没有试图奉承评审或掩饰疑虑。','Her guileless question showed exactly what she was thinking / without any attempt to flatter the panel / or hide her doubts.','guileless 修饰 question，表示坦率；without 并列说明没有欺瞒或讨好。','说话直率且不隐藏真实想法，符合 s2。'),M('The guileless witness invented a false story to trick the investigators.','The deceitful witness invented a false story to trick the investigators.','故意编造谎言是欺骗，不是 guileless。'),[Q('guileless',1,1,'A guileless person is?','honest and without a wish to deceive','skilled at concealing a fraud','unable to speak clearly','guileless 表示诚实、没有欺骗心思。'),Q('guileless',2,2,'A guileless remark is likely to be?','open and direct','carefully designed to mislead','a sudden loud noise','坦率直接的话语可以是 guileless。'),Q('guileless',3,1,'Which behavior seems guileless?','admitting a mistake without making excuses','hiding evidence to shift blame','pretending not to recognize a friend','坦承错误体现坦诚。'),Q('guileless',4,2,'The suffix -less in guileless suggests?','without guile','full of tricks','belonging to a court','-less 表示“没有”。')]);
P('guilt','guilt 源自古英语 gylt，可指做错事后的内疚感，也可指犯下罪行的事实或法律上的罪责。',C('guilt.s2','刑事司法','The jury found no evidence linking Mara to the break-in, so the court could not establish her guilt.','陪审团没有发现把玛拉与入室盗窃联系起来的证据，因此法院无法认定她有罪。','The jury found no evidence linking Mara to the break-in / so the court could not establish / her guilt.','establish guilt 表示认定罪责；so 引出缺乏证据的结果。','句子讨论法院能否认定犯罪责任，对应 s2。'),M('The court established his guilt even though the jury found that he had not committed the crime.','The court cleared him of guilt after the jury found that he had not committed the crime.','陪审团认定未犯罪时，法院不能同时认定其有罪。'),[Q('guilt',1,1,'Guilt after a mistake is?','a bad feeling about having done something wrong','a legal permit to enter a building','a sudden change in the wind','guilt 可指做错事后的内疚。'),Q('guilt',2,2,'In a criminal trial, guilt refers to?','responsibility for having committed a crime','a witness’s nervous feeling only','the judge’s personal clothing','法律语境中的 guilt 指犯罪责任。'),Q('guilt',3,1,'A person may feel guilt because they?','regret causing someone harm','have received a harmless greeting','are standing halfway across a room','伤害他人后后悔会感到内疚。'),Q('guilt',4,2,'Which phrase uses the legal sense of guilt?','The evidence established his guilt.','She felt guilt about forgetting a birthday.','He felt guilty about the delay.','establish guilt 常用于法律责任。')]);
P('guiltless','guiltless 由 guilt 加 -less 构成，指没有犯罪或过错责任，也可表示不感到内疚。',C('guiltless.s1','调查结论','After the records confirmed that she had been abroad that night, the investigators declared her guiltless of the theft.','记录证实她当晚在国外后，调查人员宣布她对这起盗窃案无罪。','After the records confirmed that she had been abroad that night / the investigators declared her guiltless / of the theft.','guiltless of + 罪行表示没有该项罪责；after 从句说明判断依据。','有行程记录排除涉案责任，符合无罪义。'),M('The guiltless suspect was convicted after investigators proved that he had committed the theft.','The guilty suspect was convicted after investigators proved that he had committed the theft.','已证明实施盗窃并被定罪的人不是 guiltless。'),[Q('guiltless',1,1,'A guiltless person is?','not guilty of the offense','certain to have committed a crime','unable to feel physical pain','guiltless 表示无罪。'),Q('guiltless',2,1,'A guiltless person?','has no blame for the offense','has confessed to the offense','was the only witness','guiltless 也可指没有过错责任。'),Q('guiltless',3,1,'Which finding supports calling someone guiltless?','reliable records show they were elsewhere','a witness identifies them at the scene','they admit committing the offense','可靠证据表明其不在现场支持无罪判断。'),Q('guiltless',4,1,'The suffix -less in guiltless means?','without guilt','more guilty','in the past','-less 表示“没有”。')]);
P('guilty','guilty 由 guilt 加 -y 构成，可指触犯法律的，也可形容因过错而感到内疚。',C('guilty.s2','个人感受','Nina felt guilty for ignoring her friend’s calls, so she apologized and offered to help with the move.','妮娜因为忽略朋友的电话而感到内疚，于是道歉并主动帮忙搬家。','Nina felt guilty for ignoring her friend’s calls / so she apologized / and offered to help with the move.','feel guilty for/about + 行为或事情表示为此内疚；so 引出补救行动。','她为忽略朋友而自责，体现内疚义 s2。'),M('Nina felt guilty for helping her friend, although she had done nothing wrong and had no reason to regret it.','Nina felt proud of helping her friend, although she had done nothing wrong.','无过错且不后悔却说为此内疚，情感与原因不符。'),[Q('guilty',1,1,'A guilty person in court has?','been found to have committed the offense','been proved absent from the event','been appointed as a guardian','guilty 可指被认定有罪。'),Q('guilty',2,2,'To feel guilty is to feel?','bad about something one did','certain that another person is guilty','happy about a harmless success','feel guilty 表示感到内疚。'),Q('guilty',3,1,'Which person may feel guilty?','someone who regrets breaking a promise','someone who has no connection to the event','someone who is giving a guitar lesson','违背承诺后后悔可能感到内疚。'),Q('guilty',4,2,'“The guilty verdict” refers to a decision that?','finds the accused responsible for the crime','clears the accused of every charge','describes the accused’s mood only','guilty verdict 指有罪裁决。')]);
P('guinea','guinea 既指几内亚一带或以其命名的事物，也指英国旧金币几尼；guinea pig 的名称来源并非字面上的“几内亚猪”。',C('guinea.s1','宠物饲养','The children refilled the guinea pig’s water bottle and offered it fresh hay before cleaning the cage.','孩子们给豚鼠的水瓶续水，并在清理笼子前给它添了新鲜干草。','The children refilled the guinea pig’s water bottle / and offered it fresh hay / before cleaning the cage.','guinea pig 是固定复合词，指豚鼠；所有格 pig’s 标出水瓶所属。','宠物笼中动物吃干草、饮水，符合豚鼠义 s1。'),M('The children kept a guinea pig as a bird that flew around the cage.','The children kept a budgerigar as a bird that flew around the cage.','豚鼠是啮齿动物，不是会飞的鸟。'),[Q('guinea',1,1,'A guinea pig is?','a small furry pet rodent','an old British gold coin','a strong ocean current','guinea pig 指豚鼠。'),Q('guinea',2,2,'A guinea was historically?','a British gold coin worth twenty-one shillings','a modern paper banknote','a type of guitar string','旧币 guinea 曾值二十一先令。'),Q('guinea',3,3,'In the name Guinea-Bissau, Guinea is?','part of a country name','the name of a pet rodent only','a legal term for guilt','Guinea 也出现在国家名称中。'),Q('guinea',4,1,'The expression “guinea pig” commonly means?','a small domesticated rodent','a pig raised in West Africa','a gold coin used as a pet','该复合词指豚鼠，不是猪。')]);
P('guise','guise 经古法语 guise“方式、外表”进入英语，现多指用来隐藏真实身份或意图的外在样子。',C('guise.s1','新闻调查','The company promoted the data sale under the guise of a free service, though customers had never agreed to that use.','公司打着免费服务的幌子推广数据出售，尽管客户从未同意这种用途。','The company promoted the data sale / under the guise of a free service / though customers had never agreed / to that use.','under the guise of 表示以某种表面名义掩饰真实行为；though 引出反差。','表面称免费服务，实际出售数据，体现伪装义。'),M('The charity acted under the guise of charity while openly refusing to hide what it was doing.','The charity acted openly as a charity and disclosed what it was doing.','公开说明行为不构成借表面身份掩饰真实目的。'),[Q('guise',1,1,'A disguise or guise is?','an outward appearance that can conceal the truth','a sudden gust of wind','a small valley cut by water','guise 指外在伪装或表象。'),Q('guise',2,1,'“Under the guise of research” may imply?','research is being used as a cover for another purpose','the work has no stated purpose','a scientist is wearing a uniform','under the guise of 暗示表面名义可能掩盖目的。'),Q('guise',3,1,'A plan hidden under a friendly guise has?','a misleadingly harmless appearance','no outward appearance at all','a confirmed legal verdict','友好外表可能掩盖真实计划。'),Q('guise',4,1,'The closest meaning of guise is?','appearance or pretense','guilt','gullet','guise 与外表、伪装有关。')]);
P('guitar','guitar 经西班牙语 guitarra 等欧洲语言传入英语，最终与古希腊弦乐器名称 kithara 有关。',C('guitar.s1','音乐排练','He tuned his guitar before rehearsal, then played a quiet chord while the singer checked the opening key.','排练前他给吉他调音，随后轻轻弹了一个和弦，让歌手确认开场调性。','He tuned his guitar before rehearsal / then played a quiet chord / while the singer checked / the opening key.','tune a guitar 表示给吉他调音；while 从句表示歌手同时确认调性。','调弦、弹和弦是吉他演奏活动，符合 s1。'),M('She plucked the guitar strings, but the instrument had no strings and was played only by striking keys.','She played the keyboard by striking its keys.','吉他是拨弦乐器；无弦而敲键描述的是键盘乐器。'),[Q('guitar',1,1,'A guitar is played mainly by?','plucking or strumming its strings','blowing air through a reed','striking a set of piano keys','吉他靠拨弦或扫弦演奏。'),Q('guitar',2,1,'Before a performance, a guitarist may tune the guitar to?','make its strings sound at the correct pitches','remove every string from the instrument','change it into a wind instrument','调音是让琴弦达到正确音高。'),Q('guitar',3,1,'Which sound is commonly made on a guitar?','a plucked chord','a spoken legal verdict','a burst of gunfire','吉他可以弹奏和弦。'),Q('guitar',4,1,'A guitar belongs to which broad instrument family?','string instruments','brass instruments','percussion only','吉他属于弦乐器。')]);
P('gulf','gulf 经阿拉伯语 khalij“海湾”及欧洲语言进入英语，可指被陆地部分环绕的大海湾，也可比喻巨大差异。',C('gulf.s1','海岸地理','The fishing boat crossed the gulf before dawn and reached the sheltered harbor on the opposite shore by midmorning.','渔船黎明前穿过海湾，到上午时抵达对岸受庇护的港口。','The fishing boat crossed the gulf before dawn / and reached the sheltered harbor / on the opposite shore / by midmorning.','cross a gulf 指穿越海湾；opposite shore 表明两侧由水域分隔。','船在海岸围绕的大片海域中航行，对应地理义 s1。'),M('The map showed the gulf entirely surrounded by dry land with no connection to the sea.','The map showed a lake entirely surrounded by dry land with no connection to the sea.','与海洋不相连且被陆地完全围住的水域应称湖，不是 gulf。'),[Q('gulf',1,1,'A gulf in geography is?','a large area of sea partly enclosed by land','a narrow hallway inside a house','a small patch of gum','gulf 可指大海湾。'),Q('gulf',2,2,'A gulf between two communities is?','a major difference or division','a shared guitar lesson','a narrow physical similarity','比喻义 gulf 指巨大分歧。'),Q('gulf',3,1,'Which could cross a gulf?','a boat traveling between coastal shores','a person walking along a dry hallway','a coin placed in a pocket','船可以穿越海湾。'),Q('gulf',4,2,'“Bridge the gulf” means to?','reduce a serious difference between groups','build a bridge across a garden path only','widen a valley','bridge the gulf 常比喻缩小分歧。')]);
P('gull','gull 的词源早期记录不明，可能与凯尔特语中海鸟名称有关；该词可指常见于海岸的长翼海鸥，也可作动词表示欺骗。',C('gull.s2','网络防骗','The email tried to gull new customers with a fake prize offer, but the payment link exposed the scheme.','这封邮件试图用虚假的奖品诱骗新客户，但付款链接暴露了骗局。','The email tried to gull new customers / with a fake prize offer / but the payment link / exposed the scheme.','gull someone with something 表示用某种手段欺骗某人；but 引出骗局被发现。','虚假奖品是诱骗手段，符合动词义 s2。'),M('The message gulls readers by giving them a genuine, fully verified prize with no deception.','The message rewards readers with a genuine, fully verified prize.','真实兑现且没有欺骗的奖品不构成 gull。'),[Q('gull',1,1,'A gull is commonly?','a long-winged seabird found near coasts','a small furry pet rodent','a large land estate','gull 可指海鸥。'),Q('gull',2,2,'To gull someone is to?','trick or deceive the person','give the person a verified refund','guide the person to a safe place','动词 gull 表示欺骗。'),Q('gull',3,1,'An online fraudster may gull a target with?','a fake prize message','a clearly labeled public notice','a verified receipt','虚假奖品信息可能骗到受害者。'),Q('gull',4,2,'Which sentence uses gull as a verb?','The scammer tried to gull tourists.','A gull circled over the harbor.','The gull had long wings.','动词用法表示试图欺骗游客。')]);
P('gullet','gullet 经古法语 goulet“喉咙、窄口”进入英语，指连接口腔与胃部、供食物通过的食道。',C('gullet.s1','人体生理','After swallowing, the softened food moved down the gullet toward the stomach.','吞咽后，软化的食物沿食道向胃部移动。','After swallowing / the softened food moved down the gullet / toward the stomach.','move down the gullet 描述食物经食道下行；toward 标示方向。','句子中的通道连接吞咽与胃，符合食道义。'),M('The gullet carried air from the lungs to the stomach as the body’s main breathing tube.','The trachea carried air from the lungs; the gullet carries food toward the stomach.','gullet 是消化通道，不是呼吸气管。'),[Q('gullet',1,1,'The gullet is part of the?','digestive passage leading toward the stomach','outer ear','bloodstream','gullet 指食道。'),Q('gullet',2,1,'Food moves down the gullet after?','being swallowed','being heard','being breathed into the lungs','吞咽后食物经过食道。'),Q('gullet',3,1,'Which is closest in meaning to gullet?','esophagus','guitar','gully','esophagus 是食道。'),Q('gullet',4,1,'The gullet connects the mouth area with the?','stomach','knee joint','outer skin','食道把咽部与胃相连。')]);
P('gullible','gullible 由动词 gull“欺骗”加 -ible 构成，指容易相信他人、因而容易受骗的。',C('gullible.s1','网络安全','A gullible shopper might click a fake delivery notice without checking whether the sender’s address matches the courier.','轻信的购物者可能不核对发件地址是否属于快递公司，就点击虚假的送货通知。','A gullible shopper might click a fake delivery notice / without checking / whether the sender’s address matches the courier.','gullible 修饰 shopper，表示容易受骗；without checking 说明风险行为。','未核实发件人便相信假通知，体现易受骗。'),M('The gullible shopper verified the sender and rejected the obvious scam because she trusted no unverified claims.','The cautious shopper verified the sender and rejected the obvious scam.','认真核实信息并拒绝骗局体现谨慎，不是 gullible。'),[Q('gullible',1,1,'A gullible person is?','easily tricked because they trust too readily','unable to hear ordinary speech','skilled at detecting every scam','gullible 表示容易受骗。'),Q('gullible',2,1,'A gullible reader may believe?','a convincing but false online claim','a claim only after checking reliable evidence','nothing that anyone ever says','轻信者容易相信虚假说法。'),Q('gullible',3,1,'Which action is gullible?','sending money after an unverified prize message','checking a sender’s identity before replying','reporting a suspicious link','未核实就汇款体现轻信。'),Q('gullible',4,1,'A gullible person is the opposite of someone?','skeptical and careful about evidence','easily deceived','quick to believe a stranger','skeptical 表示谨慎怀疑。')]);
P('gullibly','gullibly 是 gullible 的副词形式，表示以轻信、容易上当的方式行事。',C('gullibly.s1','媒体识读','He gullibly repeated the rumor before checking any reliable source, and the false claim spread through the office.','他轻信地复述了谣言，没有先核查可靠来源，结果错误说法在办公室里传播开来。','He gullibly repeated the rumor / before checking any reliable source / and the false claim spread / through the office.','gullibly 修饰 repeated，说明复述谣言时轻信未核实；before 标出核查本应先做。','没有核实便相信并转述谣言，符合副词义。'),M('She gullibly checked three independent sources before sharing the claim and rejected it when they disagreed.','She carefully checked three independent sources before sharing the claim.','核实多个可靠来源并谨慎处理信息不是轻信地行事。'),[Q('gullibly',1,1,'To act gullibly is to act?','with too much trust and too little caution','with careful doubt and verification','with sudden physical force','gullibly 表示轻信地。'),Q('gullibly',2,1,'Which sentence uses gullibly correctly?','He gullibly believed the unverified prize message.','He gullibly confirmed the message with the official company.','He gullibly refused to accept any evidence at all.','未核实就相信消息体现 gullibly。'),Q('gullibly',3,1,'Someone who gullibly forwards a rumor has?','shared it without checking whether it is true','verified it with several reliable sources','written a correction after research','轻信转发通常没有先核实。'),Q('gullibly',4,1,'The adverb gullibly most directly modifies?','the manner of believing or trusting','the number of messages','the color of a screen','副词说明相信或信任的方式。')]);
P('gully','gully 可能与古英语或北欧语中“沟、冲沟”一类词有关，指雨水冲刷形成的小峡谷，也可指排水沟。',C('gully.s2','城市排水','Workers cleared leaves from the roadside gully so storm water could drain away from the pavement.','工人清除了路边排水沟里的落叶，让暴雨积水从人行道旁排走。','Workers cleared leaves from the roadside gully / so storm water could drain away / from the pavement.','roadside gully 指路边排水沟；so 从句说明清理的目的。','沟渠用于排走路面积水，对应排水沟义 s2。'),M('The roadside gully blocked drainage because workers had built it as a solid wall with no channel.','The roadside wall blocked drainage because it had no channel.','没有通道的墙不能承担排水沟的排水功能。'),[Q('gully',1,1,'A gully formed by rain is?','a small steep valley cut by flowing water','a broad level plain','an indoor staircase','流水侵蚀可形成小峡谷。'),Q('gully',2,2,'A roadside gully may be used to?','carry rainwater away','store drinking glasses','support a guitar string','排水沟用于引走雨水。'),Q('gully',3,1,'Which feature is most likely a gully?','a narrow channel eroded into a hillside','a flat area untouched by water','a large harbor partly enclosed by land','侵蚀出的狭长沟谷是 gully。'),Q('gully',4,2,'In a drainage system, a gully is closest to a?','channel','hallway rug','gold coin','排水沟是水流通道。')]);
P('gulp','gulp 是拟声来源的英语动词，指快速而明显地吞咽，也可描述因紧张而咽一下。',C('gulp.s1','餐桌礼仪','He gulped a mouthful of water after the long run, then slowed down and took smaller sips.','长跑后他大口咽下一口水，随后放慢速度改为小口啜饮。','He gulped a mouthful of water after the long run / then slowed down / and took smaller sips.','gulp water 表示快速吞咽；后文 smaller sips 与先前的大口喝形成对照。','先急促地吞下一大口水，符合 s1。'),M('She gulped the soup by sipping one tiny spoonful over an hour.','She sipped the soup by taking one tiny spoonful over an hour.','一小时内小口慢饮与快速吞咽相反。'),[Q('gulp',1,1,'To gulp a drink is to?','swallow it quickly, often in large mouthfuls','sip it very slowly','pour it onto the floor','gulp 指快速大口吞咽。'),Q('gulp',2,1,'A nervous person might gulp when?','swallowing suddenly before speaking','sleeping soundly all night','quietly reading a map','紧张时可能突然咽一下。'),Q('gulp',3,1,'Which action is gulping?','drinking a glass of water in several quick swallows','tasting a drink with a tiny sip','holding a glass without drinking','几口快速喝下符合 gulp。'),Q('gulp',4,1,'A gulp is?','a quick act of swallowing','a long narrow valley','a gold coin','gulp 可作快速吞咽的一口或动作。')]);
P('gum','gum 词源依具体词义而异：牙龈义来自古英语 gōma，树胶义经古法语源自希腊语 kommi；口香糖是可咀嚼的胶状物。',C('gum.s2','日常购物','The shopkeeper kept sugar-free gum beside the register for customers who wanted something to chew after lunch.','店主把无糖口香糖放在收银台旁，供午饭后想嚼点东西的顾客购买。','The shopkeeper kept sugar-free gum beside the register / for customers who wanted something to chew / after lunch.','gum 在 sugar-free gum 中指口香糖；something to chew 解释其用途。','顾客购买后咀嚼而不吞下，符合口香糖义 s2。'),M('He stuck a piece of chewing gum onto the envelope to glue it, then called it a tooth.','He used glue to seal the envelope and put the chewing gum in his mouth.','可咀嚼的口香糖不是牙齿；用于粘合时应说 glue。'),[Q('gum',1,1,'Chewing gum is?','a flavored substance chewed but usually not swallowed','the hard outer layer of a tooth','a piece of paper','口香糖是咀嚼但通常不吞下的物质。'),Q('gum',2,2,'The gums in your mouth are?','the firm tissue around the teeth','sweet candy used as a snack','the strings on a guitar','gum 也指牙龈。'),Q('gum',3,3,'Tree gum is often?','a sticky substance that may be used as an adhesive','a metal shell fired from a cannon','a narrow passage in a house','树胶是黏性物质。'),Q('gum',4,4,'To gum an envelope shut means to?','stick it using an adhesive','chew it like candy','place it beside a guitar','动词 gum 可指用胶粘合。')]);
P('gun','gun 的词源可能与古英语女性名 Gunnhild 的缩写有关，早期用于称呼火炮，后泛指枪械；口语中 gun an engine 表示猛加油门。',C('gun.s3','驾驶安全','The driver gunned the engine briefly to merge with the fast-moving traffic, then eased off once the car was in the lane.','司机短暂猛踩油门并入快速行驶的车流，车辆进入车道后便松开了油门。','The driver gunned the engine briefly / to merge with the fast-moving traffic / then eased off / once the car was in the lane.','gun the engine 是口语表达，指突然加大引擎转速；once 引出完成并线后的动作。','短暂提高引擎转速完成并线，对应动词义 s3。'),M('She gunned the engine by switching it off and leaving the car motionless.','She stopped the engine by switching it off and leaving the car motionless.','关闭引擎与提高转速相反。'),[Q('gun',1,1,'A gun that fires bullets is?','a firearm used as a weapon','a musical string instrument','a water-drainage channel','gun 常指发射子弹的枪械。'),Q('gun',2,2,'A naval gun is generally?','a large weapon that fires shells','a small piece of chewing gum','a legal verdict','gun 也可指发射炮弹的大型武器。'),Q('gun',3,3,'To gun an engine is to?','increase its speed suddenly','turn it off for the night','fill it with water','gun the engine 表示猛加油门。'),Q('gun',4,1,'Which phrase uses gun as a verb?','She gunned the car down the track.','He cleaned the gun carefully.','The gun fired once.','动词 gun 可指使发动机快速加速。')]);
P('gun down','gun down 是 gun 与 down 构成的短语动词，表示用枪射击并杀死某人；常见于新闻或历史叙述。',C('gun down.s1','历史新闻','The report stated that the unarmed guard was gunned down outside the station, and investigators later identified the attacker.','报道说那名未持武器的警卫在车站外遭枪杀，调查人员后来确认了袭击者身份。','The report stated that the unarmed guard was gunned down outside the station / and investigators later identified / the attacker.','be gunned down 是 gun down 的被动形式，意为遭枪击身亡；outside 标示地点。','句子明确说明警卫被枪击致死，符合短语义。'),M('The report said the guard was gunned down, but immediately confirmed that nobody fired a weapon and he was unharmed.','The report said the guard was threatened, but no one fired a weapon and he was unharmed.','没有开枪且无人受伤，与“遭枪击杀害”矛盾。'),[Q('gun down',1,1,'To gun someone down means to?','shoot and kill the person','invite the person to a gym','warn the person with a sign','gun down 指开枪射杀。'),Q('gun down',2,1,'In “The victim was gunned down,” the phrase is?','passive voice describing a fatal shooting','a description of a safe arrest','a way to say someone was congratulated','was gunned down 是被动结构，描述枪杀。'),Q('gun down',3,1,'Which context best fits gun down?','a news account of a person killed by gunfire','a report about someone missing a train','a guide to playing guitar','该短语描述枪击致死事件。'),Q('gun down',4,1,'A person who was gunned down was?','shot and killed','gently guided home','caught in a hailstorm','短语表示被枪击杀害。')]);
P('guncotton','guncotton 是 gun 与 cotton 组成的旧称，指硝化纤维素；它是一种易燃易爆材料，历史上曾用于推进剂和炸药。',C('guncotton.s1','化学安全','The museum display identified the sealed sample as guncotton and kept it behind protective glass with a warning label.','博物馆展品将密封样品标为硝化棉，并将其置于防护玻璃后，贴有警示标签。','The museum display identified the sealed sample as guncotton / and kept it behind protective glass / with a warning label.','identify a sample as 表示鉴定样品为何物；警示和隔离符合危险化学品陈列语境。','密封危险样品被标识并隔离，指硝化棉这种材料。'),M('The museum described guncotton as harmless fabric safe to handle near an open flame.','The museum described ordinary cotton as fabric, while warning visitors that guncotton is hazardous.','硝化棉并非可在明火旁安全操作的普通织物。'),[Q('guncotton',1,1,'Guncotton is?','cellulose nitrate, a hazardous energetic material','ordinary cotton used for clothing','a kind of sugar-free gum','guncotton 指硝化纤维素。'),Q('guncotton',2,1,'A museum should display guncotton?','with appropriate containment and warnings','as harmless fabric beside an open flame','as food for visitors','该材料有危险性，应按规范隔离展示。'),Q('guncotton',3,1,'The name guncotton refers to?','a nitrated cellulose material once used in explosives','a type of firearm barrel','cotton grown only near a gym','guncotton 是硝化纤维材料。'),Q('guncotton',4,1,'Which statement is accurate?','Guncotton is chemically different from ordinary cotton.','Guncotton is simply chewing gum.','Guncotton is a harmless houseplant.','硝化处理使它不同于普通棉花。')]);
P('gunfire','gunfire 由 gun 与 fire 组合而成，指枪械或火炮发射出的枪声、炮火。',C('gunfire.s1','新闻报道','Residents moved indoors when gunfire was heard near the border crossing, and local officials asked people to avoid the area.','边境口岸附近传来枪炮声后，居民转入室内，当地官员要求人们避开该区域。','Residents moved indoors when gunfire was heard / near the border crossing / and local officials asked people / to avoid the area.','gunfire 作不可数名词指枪炮射击声或炮火；when 从句说明避险触发事件。','附近听到武器射击的声音，符合 gunfire。'),M('The report called the quiet absence of any shots “gunfire” throughout the night.','The report called the repeated sound of shots “gunfire” throughout the night.','完全没有枪声不能称为 gunfire。'),[Q('gunfire',1,1,'Gunfire means?','shots fired from guns','a group of musical strings','a meal served in a gym','gunfire 指枪炮射击。'),Q('gunfire',2,1,'People may take shelter when they hear gunfire because?','it can signal nearby shooting and danger','it means a guitar concert has started','it is a harmless weather sound','枪声可能意味着附近有危险。'),Q('gunfire',3,1,'Which phrase is natural?','Gunfire was heard in the distance.','A gunfire was heard in the distance.','The gunfire were heard in the distance.','gunfire 通常作不可数名词。'),Q('gunfire',4,1,'A report of gunfire describes?','the sound or occurrence of shots','a person who repairs guns','a warning about hail','gunfire 可指枪声或射击事件。')]);
P('gunpowder','gunpowder 由 gun 与 powder 组成，指早期火器及烟花使用的爆炸性粉末。',C('gunpowder.s1','博物馆展陈','The museum’s display explained how gunpowder changed early warfare, while keeping the historical sample sealed behind glass.','博物馆的展览介绍了火药如何改变早期战争，同时把历史样品密封陈列在玻璃后。','The museum’s display explained how gunpowder changed early warfare / while keeping the historical sample sealed / behind glass.','gunpowder 作不可数名词指火药；while 引出展示样品时的安全做法。','展品说明其用于早期火器，符合 gunpowder。'),M('The label called the harmless water in the bottle gunpowder, though it could neither burn nor explode.','The label called the material in the sealed container gunpowder and warned visitors not to handle it.','普通水不能称作火药；该词指特定的爆炸性粉末。'),[Q('gunpowder',1,1,'Gunpowder is?','an explosive powder historically used in guns and fireworks','a harmless liquid used for drinking','a stringed musical instrument','gunpowder 指火药。'),Q('gunpowder',2,1,'Early firearms used gunpowder to?','propel a projectile','tune a guitar','drain rainwater','火药曾用于推动枪械弹丸。'),Q('gunpowder',3,1,'A museum handling historical gunpowder should?','keep it appropriately sealed and controlled','let visitors test it with an open flame','store it beside food samples','火药需要受控处理。'),Q('gunpowder',4,1,'Which is a related use of gunpowder?','some traditional fireworks','making chewing gum','building a habitat','火药也曾用于烟花。')]);
P('gush','gush 可能源于模仿液体急速涌出的声音，可指液体突然大量流出，也可指过分热情地称赞。',C('gush.s2','书评交流','When asked about the new novel, Leo gushed about its characters and recommended it to everyone in the reading group.','有人问起这本新小说时，利奥滔滔不绝地称赞书中人物，还向读书会的每个人推荐。','When asked about the new novel / Leo gushed about its characters / and recommended it / to everyone in the reading group.','gush about + 对象表示热情地谈论或称赞；asked about 引出话题。','他说起小说人物时兴奋地连连称赞，符合 s2。'),M('The reviewer gushed about the novel by refusing to praise any part of it and calling it worthless.','The reviewer criticized the novel by refusing to praise it and calling it worthless.','拒绝称赞并加以贬低是批评，不是 gush about。'),[Q('gush',1,1,'Water may gush from a broken pipe when it?','flows out suddenly in a large amount','dries without moving','turns into a solid wall','gush 可指液体喷涌。'),Q('gush',2,2,'To gush about a performance is to?','praise it with excessive enthusiasm','criticize it in a neutral report','stop it from taking place','gush about 表示热情洋溢地称赞。'),Q('gush',3,1,'Which sentence uses gush as a verb for liquid?','Water gushed through the open gate.','She gushed about the singer’s voice.','The gusher praised every guest.','水从闸门大量涌出是液体义。'),Q('gush',4,3,'A gush can be?','a sudden large flow of liquid','a legal verdict','a person who cuts hair','名词 gush 也指突然涌出的大量液体。')]);
P('gusher','gusher 由 gush 加施事者后缀 -er 构成，可指压力使油自行喷出的油井，也可指过分热情地说话或称赞的人。',C('gusher.s2','演讲风格','The host was such a gusher about the new restaurant that she praised every dish before the guests had even tasted it.','主持人谈到那家新餐馆时热情过头，客人还没尝菜，她就把每道菜都夸了一遍。','The host was such a gusher about the new restaurant / that she praised every dish / before the guests had even tasted it.','gusher 指言谈过分热情的人；such ... that 引出其夸赞表现。','她对餐馆滔滔不绝地夸赞，体现 s2。'),M('The gusher gave a restrained review, mentioning one small compliment and no other praise.','The reserved speaker gave a restrained review with only one small compliment.','克制地只说一句好话并非过分热情的 gusher。'),[Q('gusher',1,1,'An oil-well gusher is a well from which oil?','rushes out under natural pressure','is pumped only by hand from a bucket','has already turned into stone','gusher 可指自喷油井。'),Q('gusher',2,2,'A person called a gusher tends to?','praise or talk with excessive enthusiasm','remain silent at every event','repair pipes for a living','比喻义指过分热情、爱夸赞的人。'),Q('gusher',3,1,'Which is most likely a gusher about a film?','someone who keeps praising every scene excitedly','someone who refuses to discuss the film','someone who checks the theater’s fire alarm','滔滔不绝称赞影片符合该比喻义。'),Q('gusher',4,2,'The suffix -er in gusher can identify?','a person or thing that gushes','a place where people live','the past tense of gush','-er 可构成施事者或工具名词。')]);
P('gust','gust 的早期来源尚不确定；现代英语中指突然增强的一阵风，常持续时间不长。',C('gust.s1','天气预报','A sudden gust knocked the cyclist’s hat into the grass, so she stopped to retrieve it before continuing.','一阵突如其来的风把骑车人的帽子吹进草地，她停下来捡起帽子后才继续骑行。','A sudden gust knocked the cyclist’s hat into the grass / so she stopped to retrieve it / before continuing.','gust 指突然一阵较强的风；so 表示帽子被吹落后的反应。','短暂风力突然增强并吹走帽子，符合阵风义。'),M('A gust of wind stayed perfectly still for several hours without moving any leaves.','A calm period had no gusts of wind and left the leaves still.','完全静止数小时的空气不是突然增强的一阵风。'),[Q('gust',1,1,'A gust is?','a sudden strong burst of wind','a slow steady underground river','a small quantity of chewing gum','gust 指阵风。'),Q('gust',2,1,'A gust might?','blow a loose hat off someone’s head','keep every leaf motionless in a storm','turn a hallway into a room','阵风可能吹走帽子。'),Q('gust',3,1,'Which phrase is natural?','a gust of wind','a gust of guilt','a gust of guitar','gust 常与 wind 搭配。'),Q('gust',4,1,'Compared with a gentle breeze, a gust is usually?','a sudden stronger burst','a permanent absence of air','a long calm period','gust 突然且风力较强。')]);
P('gusty','gusty 由 gust 加 -y 构成，形容天气有阵风、风力时强时弱。',C('gusty.s1','户外活动','The forecast called for gusty conditions, so the sailing club postponed its beginner lesson until the wind became steadier.','天气预报称会有阵风，因此帆船俱乐部把初学者课程推迟到风势更稳定时。','The forecast called for gusty conditions / so the sailing club postponed its beginner lesson / until the wind became steadier.','gusty 修饰 conditions，表示多阵风；until 从句指出延期到何时。','阵风使初学者帆船课延期，符合 gusty。'),M('The gusty afternoon had completely motionless air and no changes in wind speed.','The calm afternoon had completely motionless air and no changes in wind speed.','毫无风力变化的天气应称 calm，而非 gusty。'),[Q('gusty',1,1,'Gusty weather has?','sudden bursts of stronger wind','no wind at all','constant heavy rain but no wind','gusty 指有阵风的。'),Q('gusty',2,1,'On a gusty day, a small boat may?','be pushed about by changing bursts of wind','remain unaffected by all air movement','turn into a harbor','阵风会影响小船航行。'),Q('gusty',3,1,'The suffix -y in gusty means?','characterized by or having gusts','without any gusts','the person who measures wind','-y 构成“有……特征的”形容词。'),Q('gusty',4,1,'A gusty forecast might lead organizers to?','postpone a wind-sensitive outdoor activity','schedule an indoor lecture outdoors','expect perfectly still air','多阵风可能影响户外活动安排。')]);
P('gut','gut 源自古英语 guttas，可指消化道或动物内脏，也可比喻勇气、事物核心，作形容词时表示本能的。',C('gut.s5','直觉判断','My gut reaction was to question the offer, although I waited for the written details before deciding whether it was safe.','我的本能反应是质疑这项提议，不过我等到拿到书面细节后才决定是否安全。','My gut reaction was to question the offer / although I waited for the written details / before deciding whether it was safe.','gut reaction 指未经细想的直觉反应；although 表示随后仍审慎核实。','第一反应来自直觉而非推理，符合 s5。'),M('His gut instinct was carefully calculated from the full report and a step-by-step statistical analysis.','His considered judgment was calculated from the full report and a step-by-step statistical analysis.','基于完整分析作出的判断不是 gut 所指的直觉。'),[Q('gut',1,1,'The gut is part of the body’s?','digestive system','hearing system','outer skeleton','gut 可指消化道。'),Q('gut',2,2,'Someone with guts has?','courage and determination','a strong taste for gum','a large collection of guitars','have guts 可表示有胆量。'),Q('gut',3,4,'The gut of an argument is its?','most important central part','outer decorative border','least relevant detail','gut 可比喻核心或实质。'),Q('gut',4,5,'A gut feeling is based mainly on?','instinct rather than careful reasoning','a full legal investigation','a weather forecast','gut feeling 指直觉感受。')]);
P('guy','表示“男人、家伙”的 guy 从 Guy Fawkes 的名字演变而来；另一同形词 guy 还可指固定帐篷等物的拉索。',C('guy.s3','露营搭建','Before the storm arrived, the campers tightened each guy so the tent would remain secure against the wind.','暴风雨来临前，露营者拉紧每根固定绳，让帐篷在风中保持稳固。','Before the storm arrived / the campers tightened each guy / so the tent would remain secure / against the wind.','guy 在露营语境指固定帐篷的拉索；so 从句说明拉紧的目的。','用绳索固定帐篷以防风，符合 s3。'),M('They loosened every guy rope to make the tent safer and more firmly anchored in the wind.','They tightened every guy rope to make the tent safer and more firmly anchored in the wind.','要固定帐篷应拉紧而不是放松支绳。'),[Q('guy',1,1,'In informal speech, a guy is often?','a man or person','a small valley','a type of mineral','guy 常指男人或某人。'),Q('guy',2,2,'In “You guys can come in,” guys addresses?','a group of people','one rope holding a tent','a single engine','guys 可口语称呼一群人。'),Q('guy',3,3,'A tent guy is?','a rope used to hold the tent steady','a person who sells tickets','a kind of guitar','guy 可指帐篷拉索。'),Q('guy',4,1,'Which meaning fits “I met a nice guy at work”?','a man or person','a rope securing a tent','a water channel','该句用 guy 指一个人。')]);
P('guys','guys 是 guy 的复数形式，口语中常用来称呼或指一群人；使用时要注意语境和受众。',C('guys.s1','团队沟通','The coach told the guys to bring their own water bottles, then explained where the team would meet after practice.','教练让队员们带上自己的水瓶，随后说明训练后全队集合的地点。','The coach told the guys to bring their own water bottles / then explained / where the team would meet after practice.','guys 是复数口语称呼；tell someone to do something 为常见结构。','教练用 guys 称呼多名队员，对应 s1。'),M('The coach addressed one player as “guys” and then said the group contained exactly one person.','The coach addressed the team as “guys” and then referred to its several players.','guys 是复数称呼，不能与“恰好一人”的语境对应。'),[Q('guys',1,1,'In casual speech, guys can refer to?','a group of people','only one piece of rope','a type of gym equipment','guys 可口语称呼一群人。'),Q('guys',2,1,'“Hi, guys” is usually said to?','several people being addressed','one object on a table','a single gust of wind','该表达面向一群人。'),Q('guys',3,1,'The singular form of guys is?','guy','guyes','guying','guys 是 guy 的复数形式。'),Q('guys',4,1,'In a sentence about men arriving, guys is?','a plural noun for people','the past tense of guide','a singular formal title','guys 在此作人的复数名词。')]);
P('guzzle','guzzle 可能与中古英语中“吞咽、喉咙”一类词形有关，指贪婪或急促地大量吃喝。',C('guzzle.s1','餐饮习惯','After the race, the runner guzzled a bottle of water too quickly and had to pause before eating.','比赛后，跑步者急匆匆地灌下一瓶水，只好停一会儿再吃东西。','After the race / the runner guzzled a bottle of water too quickly / and had to pause / before eating.','guzzle a drink 表示急促、大量地喝；too quickly 点出动作方式。','急促地喝完整瓶水，符合 s1。'),M('She guzzled the tea by taking one careful teaspoon over the entire afternoon.','She sipped the tea by taking one careful teaspoon over the entire afternoon.','整下午小口慢饮与急促大量饮用相反。'),[Q('guzzle',1,1,'To guzzle a drink is to?','drink it quickly and greedily','sip it slowly and carefully','pour it into a sealed bottle','guzzle 指狂饮。'),Q('guzzle',2,1,'A person who guzzles food tends to?','eat a large amount quickly','taste one small bite over an hour','refuse all food','guzzle 也可指狼吞虎咽。'),Q('guzzle',3,1,'Which action is guzzling?','rapidly drinking a whole bottle after exercise','taking a small sip to check the flavor','reading a menu without ordering','快速大量喝饮料符合 guzzle。'),Q('guzzle',4,1,'The closest contrast to guzzle is?','sip','gulp down','devour','sip 表示小口慢饮。')]);
P('gym','gym 是 gymnasium 的口语缩略形式，指进行锻炼的健身房或体育馆；在学校口语中也可指体育课。',C('gym.s2','学校课程','We have gym after lunch on Tuesdays, so I keep my trainers in a locker at school.','我们星期二午饭后有体育课，所以我把运动鞋放在学校储物柜里。','We have gym after lunch on Tuesdays / so I keep my trainers / in a locker at school.','have gym 在学校语境指上体育课；trainers 是英式“运动鞋”。','课表里的 gym 指体育课，而非健身房场所义 s2。'),M('The timetable listed gym as a school subject, but described it as a meal eaten at lunchtime.','The timetable listed gym as a physical education class after lunch.','课表中的 gym 是体育课，不是午餐食物。'),[Q('gym',1,1,'A gym is usually a place for?','physical exercise','storing old court records','growing seaweed','gym 常指健身房或体育馆。'),Q('gym',2,2,'At school, “We have gym at ten” may mean?','a physical education class','a gold coin lesson','a visit to a harbor','gym 可口语指体育课。'),Q('gym',3,1,'A person going to the gym may bring?','workout clothes and trainers','a fishing boat','a hall of residence contract','健身者会带运动装备。'),Q('gym',4,1,'Gym is a shortened form of?','gymnasium','guiltless','guncotton','gym 是 gymnasium 的缩略形式。')]);
P('gymnasium','gymnasium 经拉丁语源自希腊语 gymnasion，古代与体育训练场有关；现代指用于体育或锻炼的大型场所。',C('gymnasium.s1','学校设施','The school reserved its gymnasium for the indoor tournament because the hall had enough space for two courts and a small audience.','学校把体育馆留给室内比赛，因为馆内有足够空间容纳两个球场和少量观众。','The school reserved its gymnasium for the indoor tournament / because the hall had enough space / for two courts and a small audience.','gymnasium 指体育馆；because 从句说明场地适合比赛的原因。','室内球场和观众席表明这是体育活动场馆，符合 s1。'),M('The school held the basketball tournament in its gymnasium, which had no hall or space for exercise.','The school held the basketball tournament in its gymnasium, a large hall for sports.','用于篮球比赛的场地应有体育活动空间，不能同时说没有场馆。'),[Q('gymnasium',1,1,'A school gymnasium is typically?','a large hall used for sports and exercise','a room used only for quiet dining','a small legal office','gymnasium 可指体育馆。'),Q('gymnasium',2,2,'A community gymnasium may contain?','exercise equipment for members','a harbor and a fishing boat','a courtroom jury box','gymnasium 也可指健身中心。'),Q('gymnasium',3,1,'Which event would most likely use a gymnasium?','an indoor basketball tournament','a deep-sea voyage','a courtroom appeal','体育馆可举办室内比赛。'),Q('gymnasium',4,2,'The word gymnasium is the full form behind?','gym','gully','guilt','gym 是 gymnasium 的缩略词。')]);
P('gymnastic','gymnastic 源自希腊语 gymnastikos，形容体操训练或展现体操般灵巧身体技能的动作。',C('gymnastic.s1','舞台表演','The dancer made a gymnastic leap over the low barrier and landed steadily on the marked stage.','舞者做了一个体操般灵巧的跳跃越过矮栏，并稳稳落在标记好的舞台上。','The dancer made a gymnastic leap over the low barrier / and landed steadily / on the marked stage.','gymnastic 修饰 leap，形容动作需要力量和灵巧；and 连接连续动作。','跳跃展现身体技巧与灵巧，符合 s1。'),M('The gymnast performed a gymnastic movement while remaining completely still and making no physical motion.','The performer described the movement as gymnastic because it required strength and agility.','完全静止、没有身体动作不可能体现体操般的技巧。'),[Q('gymnastic',1,1,'A gymnastic movement requires?','strength and physical agility','no movement at all','a legal document','gymnastic 可指需要力量和灵巧的动作。'),Q('gymnastic',2,1,'A gymnastic leap would be?','a controlled, skillful physical jump','a slow written explanation','a sudden gust of wind','灵巧的身体跳跃具有体操般技巧。'),Q('gymnastic',3,1,'The suffix in gymnastic marks it as?','an adjective describing gymnastics or agility','a plural form of gym','a person who runs a gym','gymnastic 是形容词。'),Q('gymnastic',4,1,'Which phrase is natural?','gymnastic skill','gymnastic guilt','gymnastic gunpowder','gymnastic 常修饰动作和技能。')]);
P('gymnastics','gymnastics 经拉丁语和法语源自希腊语 gymnastikos，指需要力量、平衡和控制的体操运动。',C('gymnastics.s1','体育比赛','The gymnastics team practiced on the balance beam for an hour before the regional competition.','体操队在地区比赛前于平衡木上练习了一个小时。','The gymnastics team practiced on the balance beam / for an hour / before the regional competition.','gymnastics 指体操运动；practice on + 器械说明训练项目。','平衡木训练和比赛属于体操项目。'),M('Her gymnastics routine required no balance, strength, coordination, or physical movement.','Her reading routine required no balance, strength, coordination, or physical movement.','没有身体动作和身体控制要求的活动不是 gymnastics。'),[Q('gymnastics',1,1,'Gymnastics is a sport involving?','strength, balance, and controlled exercises','only long-distance swimming','playing a string instrument','体操需要力量、平衡和身体控制。'),Q('gymnastics',2,1,'A balance beam is used in?','gymnastics','a courtroom trial','a weather forecast','平衡木是体操器械。'),Q('gymnastics',3,1,'A gymnast preparing for competition will likely?','practice routines on apparatus','guzzle water throughout the performance','operate a fishing boat','体操运动员会训练成套动作。'),Q('gymnastics',4,1,'Which phrase names the sport?','artistic gymnastics','guilty gymnastics','gulf gymnastics','artistic gymnastics 是体操项目。')]);
P('gynecologist','gynecologist 由 gynecology 加表示专科医生的 -ist 构成，指接受女性生殖健康训练的医生。',C('gynecologist.s1','医疗服务','Her gynecologist reviewed the test results with her and explained which follow-up appointment would be appropriate.','她的妇科医生和她一起查看检查结果，并说明适合预约哪种后续门诊。','Her gynecologist reviewed the test results with her / and explained / which follow-up appointment would be appropriate.','gynecologist 指妇科医生；review ... with someone 表示共同查看并解释。','医生评估相关检查并安排后续照护，符合专科医生义。'),M('The gynecologist specialized in repairing car engines and had no medical training.','The mechanic specialized in repairing car engines and had no medical training.','没有医学训练的汽车修理工不是妇科医生。'),[Q('gynecologist',1,1,'A gynecologist is a physician specializing in?','women’s reproductive health','weather systems','musical instruments','gynecologist 指妇科医生。'),Q('gynecologist',2,1,'A patient might see a gynecologist for?','care related to reproductive health','a guitar tuning lesson','help with a roof gutter','该专科提供女性生殖健康诊疗。'),Q('gynecologist',3,1,'The suffix -ist in gynecologist helps form a word for?','a specialist or practitioner','a type of mineral','a sudden wind','-ist 常表示从事某领域的人员。'),Q('gynecologist',4,1,'A gynecologist belongs to which profession?','medicine','carpentry','farming','妇科医生属于医疗职业。')]);
P('gynecology','gynecology 由希腊语 gyne“女性”及 -logy“学科”构成，指研究女性生殖系统及其疾病的医学领域。',C('gynecology.s1','医学学科','The hospital expanded its gynecology clinic so patients could receive reproductive health examinations closer to home.','医院扩充了妇科门诊，让患者能在离家更近的地方接受生殖健康检查。','The hospital expanded its gynecology clinic / so patients could receive reproductive health examinations / closer to home.','gynecology 指医学专科；so 引出扩充门诊的服务目标。','门诊提供女性生殖健康检查，符合妇科学义。'),M('The lecture described gynecology as the study of weather and ocean currents.','The lecture described meteorology and oceanography as the study of weather and currents.','天气和海洋洋流不是 gynecology 的研究对象。'),[Q('gynecology',1,1,'Gynecology is the medical study of?','the female reproductive system and related disorders','mountains and river valleys','exercise equipment','gynecology 指妇科学。'),Q('gynecology',2,1,'A gynecology clinic provides?','reproductive health care','lessons in weather forecasting','repairs for musical instruments','妇科门诊提供生殖健康照护。'),Q('gynecology',3,1,'The ending -logy in gynecology means?','a field of study','without a subject','a person who treats metal','-logy 表示学科或研究领域。'),Q('gynecology',4,1,'Which professional is associated with gynecology?','a gynecologist','a geographer','a guitar maker','gynecologist 是妇科学专科医生。')]);
P('gypsum','gypsum 经拉丁语 gypsum 源自希腊语 gypsos，指一种柔软的硫酸钙矿物，也可指用石膏处理土壤或表面。',C('gypsum.s2','农业土壤','The grower spread gypsum over the sodic soil after testing it, following the agronomist’s recommendation.','种植者检测土壤后，按照农艺师的建议撒施石膏改良钠质土。','The grower spread gypsum over the sodic soil / after testing it / following the agronomist’s recommendation.','spread gypsum over soil 指施用石膏；following 表示依据专业建议。','石膏被施用于土壤作改良处理，符合动词义 s2。'),M('The grower added gypsum to the soil but described it as a liquid animal feed.','The grower added gypsum to the soil as a mineral soil amendment.','土壤改良用矿物不能同时被称为液态动物饲料。'),[Q('gypsum',1,1,'Gypsum is a soft mineral made mainly of?','calcium sulfate','sodium chloride','cellulose nitrate','gypsum 是硫酸钙矿物。'),Q('gypsum',2,2,'A farmer may gypsum soil by?','adding gypsum as a soil treatment','planting a guitar in it','turning it into a harbor','动词 gypsum 可指用石膏处理土壤。'),Q('gypsum',3,1,'Plaster commonly contains material derived from?','gypsum','gunfire','guile','石膏是熟石膏和石膏制品的原料。'),Q('gypsum',4,2,'Which phrase uses gypsum as a mineral noun?','a sample of gypsum','to gypsum a field','gypsuming a surface','a sample of gypsum 中它作矿物名词。')]);
P('gypsy','Gypsy 是历史上对罗姆人的英语称呼，源于曾把他们误认为来自埃及的旧说法；该标签常被视为冒犯，宜用 Romani 或 Roma。',C('gypsy.s1','博物馆文字审订','The archive’s older caption used the term “Gypsy”; the revised display identifies the community as Romani and explains why the outdated label can offend.','档案馆旧说明使用了“Gypsy”一词；修订后的展板称该群体为罗姆人，并解释过时称呼为何可能冒犯。','The archive’s older caption used the term “Gypsy” / the revised display identifies the community as Romani / and explains / why the outdated label can offend.','此处在讨论历史标签而非把它当作对人的中性称呼；现代文字通常优先使用 Romani 或 Roma。','语境说明旧称的历史使用及其冒犯性，符合 source entry 的用法提示。'),M('The style guide calls “Gypsy” a universally neutral term and forbids the preferred name Romani.','The style guide notes that “Gypsy” can offend and recommends the name Romani or Roma when appropriate.','把可能冒犯的旧称说成普遍中性并禁用建议称呼，误述了当代用语建议。'),[Q('gypsy',1,1,'In modern usage, the historical label Gypsy?','can be offensive; Romani or Roma is generally preferred','is always the preferred neutral name','refers to a type of mineral','词典提示该旧称可能冒犯，建议用 Romani 或 Roma。'),Q('gypsy',2,1,'When editing a contemporary description of the Romani people, a careful writer should?','prefer Romani or Roma unless discussing the historical label','use the old label as a joke','assume every person prefers the same term','当代称呼应优先尊重 Romani/Roma 的用法。'),Q('gypsy',3,1,'Why does the exhibit put the historical word in quotation marks?','it is discussing an outdated label rather than using it as a neutral name','it is identifying a mineral sample','it is quoting a weather report','引号表示展览讨论旧标签本身。'),Q('gypsy',4,1,'The word’s historical association with Egypt is best described as?','a mistaken old belief behind the label','proof that the Romani people originated in Egypt','a medical definition','旧称源于错误的埃及来历说法。')]);
P('gyration','gyration 经拉丁语 gyratus“绕圈旋转”而来，指绕轴或沿圆形、螺旋路径转动的动作。',C('gyration.s1','物理演示','The instructor slowed the wheel’s gyration so students could observe how its marked point traced a widening circle.','讲师放慢了轮子的旋转，让学生观察标记点如何描出逐渐扩大的圆。','The instructor slowed the wheel’s gyration / so students could observe / how its marked point traced / a widening circle.','gyration 指旋转动作；so 引出放慢转动的教学目的。','轮子绕轴转动，标记点描出圆形轨迹，符合 s1。'),M('The wheel’s gyration consisted of remaining completely motionless throughout the demonstration.','The wheel’s stillness consisted of remaining completely motionless throughout the demonstration.','完全不动是静止，不是旋转。'),[Q('gyration',1,1,'A gyration is?','a turning or circular movement','a fixed legal judgment','a kind of leafy vegetable','gyration 指旋转。'),Q('gyration',2,1,'A wheel in gyration is?','moving around an axis or in a circular path','permanently motionless','being pulled into a straight line only','旋转的轮子绕轴或沿圆形路径运动。'),Q('gyration',3,1,'Which event involves gyration?','a spinning top turning on a table','a book lying still on a shelf','a person reading a quiet note','陀螺转动体现 gyration。'),Q('gyration',4,1,'Gyration is closest to?','rotation','stillness','greeting','rotation 表示旋转。')]);
P('gyre','gyre 源自希腊语 gyros“圆、环”，可指旋转或漩涡，也指海洋中大尺度的环流系统。',C('gyre.s1','海洋科学','Satellite maps showed a large ocean gyre carrying floating material slowly around the subtropical basin.','卫星地图显示，一个大型海洋环流正带着漂浮物缓慢绕亚热带海盆流动。','Satellite maps showed a large ocean gyre / carrying floating material slowly / around the subtropical basin.','ocean gyre 指海洋大尺度环流；carrying 分词短语补充环流的作用。','海水围绕海盆形成大范围循环，符合 s1。'),M('The ocean gyre moved in a straight line across the basin and never circulated.','The ocean current moved in a straight line across the basin and never circulated.','从不循环的直线水流不是 gyre。'),[Q('gyre',1,1,'An ocean gyre is?','a large circular system of ocean currents','a small indoor exercise class','a mineral used in plaster','gyre 可指海洋环流系统。'),Q('gyre',2,2,'To gyre means to?','move in a circle or spiral','remain completely still','swallow food quickly','动词 gyre 表示旋转。'),Q('gyre',3,1,'A floating object in a gyre may?','circulate around a large ocean basin','travel only in a perfectly straight path','become a guitar string','环流可能带着漂浮物绕海盆移动。'),Q('gyre',4,2,'A gyre is most closely associated with?','circular motion','a legal verdict','a hairdresser','gyre 的核心概念是圆形旋转。')]);
P('habit','habit 经古法语和拉丁语 habitus“习惯、状态、穿着”进入英语，可指经常做的事、难以停止的癖好，也可指修士长袍。',C('habit.s1','行为改变','She built a habit of reviewing her notes for ten minutes after dinner, which made exam preparation less stressful.','她养成了晚饭后复习十分钟笔记的习惯，因此备考压力减轻了。','She built a habit of reviewing her notes for ten minutes after dinner / which made exam preparation / less stressful.','build a habit of + -ing 表示养成某种习惯；which 从句说明结果。','每天重复复习成为固定做法，符合习惯义 s1。'),M('Checking the calendar once each morning became a habit, although she did it only once in her entire life.','Checking the calendar once each morning became a habit because she repeated it regularly.','只做过一次不能构成反复形成的习惯。'),[Q('habit',1,1,'A habit is something a person?','does regularly, often without thinking','does exactly once and never again','uses only to measure wind','habit 常指经常重复的行为。'),Q('habit',2,2,'A bad habit may be?','a repeated tendency that is hard to stop','a single unrelated accident','a legal document','habit 也可指难以停止的癖好。'),Q('habit',3,3,'A monk’s habit is?','a distinctive loose garment','a regular exercise routine','a type of hall','habit 还可指修士或修女的长袍。'),Q('habit',4,1,'Which action could become a habit?','reading for a few minutes every night','forgetting a date once','hearing one sudden gust','经常重复的夜读可形成习惯。')]);
P('habitable','habitable 经古法语源自拉丁语 habitabilis，表示适合人居住的。',C('habitable.s1','行星科学','Scientists are studying whether the planet’s atmosphere could make its surface habitable for simple organisms.','科学家正在研究这颗行星的大气层是否能使其表面适合简单生物生存。','Scientists are studying whether the planet’s atmosphere / could make its surface habitable / for simple organisms.','habitable 修饰 surface，表示适于居住或生存；whether 引出研究的问题。','研究对象是表面是否适合生物生存，符合 s1。'),M('The abandoned moon was habitable for humans despite having no breathable air, liquid water, or shelter.','The abandoned moon was uninhabitable for humans because it had no breathable air, liquid water, or shelter.','缺乏空气、水和庇护条件，不适合人类居住。'),[Q('habitable',1,1,'A habitable place is?','suitable for people or organisms to live in','impossible to enter for any reason','designed only for storing tools','habitable 表示适合居住。'),Q('habitable',2,1,'A planet may be called habitable if it?','could support life under suitable conditions','has no atmosphere or liquid water','is covered only by empty space','若可能支持生命，可称适居。'),Q('habitable',3,1,'The suffix -able in habitable means?','capable of being lived in','without a home','a person who studies planets','-able 表示能够或适于。'),Q('habitable',4,1,'Which description best fits a habitable house?','one safe and fit for people to live in','one with a collapsed roof and no utilities','one used only as a sealed laboratory sample','适合人居住的房屋是 habitable。')]);
P('habitat','habitat 源自拉丁语 habitare“居住”，指动植物自然生活的环境，也可指人的工作或居住环境。',C('habitat.s1','生态保护','The wetland is an important habitat for frogs and migratory birds, so the council restricted construction near the marsh.','这片湿地是青蛙和候鸟的重要栖息地，因此市政部门限制在沼泽附近施工。','The wetland is an important habitat for frogs and migratory birds / so the council restricted construction / near the marsh.','habitat 指物种生活的自然环境；so 说明保护栖息地的措施。','湿地为动物提供生活环境，符合 s1。'),M('The wetland was the birds’ habitat even though no birds could live there and they never visited it.','The wetland was not a habitat for those birds because they could neither live nor feed there.','没有动物能够生存或活动的地点不构成它们的栖息地。'),[Q('habitat',1,1,'An animal’s habitat is?','the natural place where it lives','a hairstyle chosen for a wedding','a court’s final decision','habitat 指栖息地。'),Q('habitat',2,2,'A person’s work habitat may mean?','the place or environment where they work','the animal species they study','a type of gym class','habitat 也可指人的工作环境。'),Q('habitat',3,1,'Protecting a wetland can protect?','the habitat of species living there','a haircut from being changed','a gust of wind','湿地为其中物种提供栖息地。'),Q('habitat',4,2,'A habitat must be connected with?','a living thing’s environment','a person’s guilt only','the act of cutting hair','habitat 的核心是生活环境。')]);
P('habitation','habitation 经古法语源自拉丁语 habitatio“居住、住所”，可指居住这一事实，也可指人居住的地方。',C('habitation.s2','历史建筑','The stone habitation stood beside the well, with a small courtyard where the family stored tools and dried herbs.','这座石砌住所位于水井旁，带有一个小院，家人在那里存放工具并晾晒草药。','The stone habitation stood beside the well / with a small courtyard / where the family stored tools / and dried herbs.','habitation 指供人居住的地方；where 从句说明小院用途。','石屋及其院落供家庭居住，对应 s2。'),M('The habitation was a vacant building where nobody lived, worked, or stayed overnight.','The warehouse was a vacant building where nobody lived, worked, or stayed overnight.','无人居住或停留的空楼不能称为住所。'),[Q('habitation',1,1,'Habitation can mean?','the fact or process of living somewhere','a tool used to cut hair','a sudden burst of wind','habitation 可指居住这一事实。'),Q('habitation',2,2,'A habitation is also?','a place where people live','a kind of mineral','a legal accusation','habitation 也指住所。'),Q('habitation',3,1,'A remote island with no permanent residents has little?','human habitation','gymnastics','guiltless conduct','无人长期居住说明人类居住稀少。'),Q('habitation',4,2,'Which phrase is natural?','a place of habitation','a gust of habitation','a guitar of habitation','place of habitation 指住所。')]);
P('habitu','habitu 是罕见的英语名词形式，表示惯例或习惯；其词形与拉丁语 habitus“状态、习惯”相关。',C('habitu.s1','词汇释义','The glossary marked habitu as an uncommon word for a custom, rather than a term used in everyday conversation.','词汇表把 habitu 标作表示惯例的罕见词，而不是日常会话中的常用词。','The glossary marked habitu as an uncommon word for a custom / rather than a term / used in everyday conversation.','habitu 在此作为名词使用；rather than 对比其词典释义和常见程度。','词典将该词列为表示惯例的罕见名词，符合 source sense。'),M('The glossary described habitu as a common everyday verb meaning “to shout loudly.”','The glossary described habitu as an uncommon noun meaning “a custom.”','把罕见名词误说成常见动词且释义无关，是词性和词义错误。'),[Q('habitu',1,1,'Habitu is listed as an uncommon word for?','a regular habit or custom','a sudden strong wind','a medical specialist','habitu 可指惯例。'),Q('habitu',2,1,'Which part of speech is habitu in this entry?','a noun','an adverb','a verb meaning “to shoot”','source entry 将 habitu 列作名词。'),Q('habitu',3,1,'A dictionary may label habitu as?','rare or uncommon','the usual everyday spelling of habit','a plural of habitat','该词条属于少见词形。'),Q('habitu',4,1,'The meaning of habitu is closest to?','custom','haircut','hailstorm','custom 表示惯例。')]);
P('habitual','habitual 由 habit 加 -ual 构成，表示经常重复、已成为习惯的。',C('habitual.s1','交通观察','The habitual early riser was already at the station when the first bus arrived.','这位习惯早起的人在首班公交到达时已经到了车站。','The habitual early riser was already at the station / when the first bus arrived.','habitual 修饰 early riser，表示此人通常如此；when 从句补充时间。','经常早起成为固定习惯，符合 s1。'),M('His habitual visit happened once in his entire life and was never repeated.','His single visit happened once in his entire life and was never repeated.','只发生一次的行为不是经常重复形成的习惯。'),[Q('habitual',1,1,'A habitual action is?','done regularly as a habit','done only once by accident','always forbidden by law','habitual 表示习惯性的。'),Q('habitual',2,1,'A habitual early riser usually?','gets up early regularly','stays awake for one unusual night only','never follows a routine','经常早起是习惯性行为。'),Q('habitual',3,1,'Which phrase is natural?','a habitual visitor','a habitual once-only event','a habitual empty room','habitual 常修饰重复发生的人或行为。'),Q('habitual',4,1,'The closest meaning of habitual is?','customary','accidental','uninhabitable','customary 表示惯常的。')]);
P('habitually','habitually 由 habitual 加副词后缀 -ly 构成，表示以习惯方式或经常重复地做某事。',C('habitually.s2','行为观察','The clerk habitually checked the closing checklist twice, even on quiet evenings when the shop had few customers.','即使在顾客不多的清静夜晚，店员也习惯把闭店清单检查两遍。','The clerk habitually checked the closing checklist twice / even on quiet evenings / when the shop had few customers.','habitually 修饰 checked，表示反复形成的做法；even 强调安静时也如此。','店员一贯重复检查清单，符合 s2。'),M('She habitually checked the lock once in her whole life and never did it again.','She once checked the lock but did not make it a regular practice.','一生只做过一次、从不重复不能称为 habitually。'),[Q('habitually',1,1,'To act habitually is to act?','in a way that has become a regular practice','without any repeated pattern','only under a court order','habitually 表示习惯性地。'),Q('habitually',2,2,'A person who habitually checks a lock?','does so repeatedly as part of a routine','checked it once by chance','has never checked it','habitually 指反复形成的做法。'),Q('habitually',3,1,'Which sentence uses habitually?','He habitually arrived before the office opened.','He arrived early one time only.','He habitually will arrive once in the future.','经常提前到达体现 habitually。'),Q('habitually',4,2,'The adverb habitually describes?','the usual or repeated manner of an action','the size of a building','the taste of chewing gum','副词说明动作惯常发生的方式。')]);
P('habituate','habituate 由 habit 相关词形发展而来，指使某人逐渐适应一种环境或刺激。',C('habituate.s1','行为训练','The trainer gradually habituated the rescue dog to the sound of traffic by rewarding calm behavior at a safe distance.','训练员在安全距离奖励狗保持平静，逐步使这只救援犬适应交通声。','The trainer gradually habituated the rescue dog to the sound of traffic / by rewarding calm behavior / at a safe distance.','habituate someone to something 表示使某人逐渐习惯某事；by 引出训练方法。','逐步让狗适应交通噪声，符合使习惯义。'),M('The trainer habituated the dog to traffic by keeping it permanently away from every traffic sound.','The trainer shielded the dog from traffic by keeping it away from every traffic sound.','完全隔离刺激并未使其适应该刺激。'),[Q('habituate',1,1,'To habituate someone to a sound is to?','help them become used to it gradually','make sure they never hear it','turn the sound into a musical instrument','habituate to 表示逐渐适应。'),Q('habituate',2,1,'A trainer may habituate a dog to traffic by?','introducing the sound gradually in a controlled setting','surprising the dog with loud noise every time','keeping the dog away from all roads forever','逐步、安全接触可以使动物适应。'),Q('habituate',3,1,'Which pattern is correct?','habituate a child to a new routine','habituate a child from a new routine','habituate a routine of a child','常见结构是 habituate someone to something。'),Q('habituate',4,1,'To habituate to a stimulus means to?','become accustomed to it','become more frightened every time','forget how to hear','该词表示使逐渐习惯。')]);
P('habituation','habituation 由 habituate 加名词后缀 -ation 构成，可指养成习惯，也指反复接触后反应逐渐减弱的习惯化过程。',C('habituation.s1','心理学实验','After several days, the repeated bell caused less startle in the mice, a response the researchers described as habituation.','几天后，反复响起的铃声对小鼠造成的惊跳反应减弱，研究人员把这种反应称为习惯化。','After several days / the repeated bell caused less startle in the mice / a response the researchers described / as habituation.','habituation 在心理学中可指反复接触后对刺激的反应减弱；as 引出研究者的术语判断。','重复铃声引发的惊跳反应下降，符合习惯化义。'),M('The experiment showed habituation because the mice reacted more strongly to the same bell after every repetition.','The experiment showed sensitization because the mice reacted more strongly to the same bell after every repetition.','对同一刺激反应逐渐增强是 sensitization，不是 habituation。'),[Q('habituation',1,1,'In psychology, habituation is?','a reduced response after repeated exposure to a stimulus','a stronger response after every repetition','a kind of muscle injury','习惯化常指反复刺激后反应减弱。'),Q('habituation',2,1,'If an animal stops startling at a familiar harmless sound, this may be?','habituation','a gust','a haircut','对熟悉无害声音反应减弱属于习惯化。'),Q('habituation',3,1,'Habituation can also refer to?','the process of forming a habit','the act of cutting hair','a sudden flow of liquid','词条也收录形成习惯的过程义。'),Q('habituation',4,1,'Habituation differs from sensitization because habituation usually?','reduces the response to a repeated stimulus','increases the response to every repetition','removes the stimulus itself','habituation 通常使反应减弱。')]);
P('hacienda','hacienda 经西班牙语进入英语，指西语美洲的大型土地庄园，也可指庄园主宅。',C('hacienda.s2','旅行住宿','The restored hacienda’s main house now serves as a small museum, while the surrounding estate remains farmland.','修复后的庄园主宅如今是一座小型博物馆，周围庄园土地仍用于农耕。','The restored hacienda’s main house now serves as a small museum / while the surrounding estate / remains farmland.','hacienda 在此指庄园主宅；while 对比建筑用途与周围土地用途。','句子具体指大型庄园的主宅，对应 s2。'),M('The hacienda was a tiny city apartment with no estate or connection to a rural property.','The apartment was a tiny city residence with no estate or rural land.','城市小公寓不是拉美大型土地庄园或其主宅。'),[Q('hacienda',1,1,'A hacienda is traditionally?','a large estate in Spanish-speaking parts of the Americas','a small indoor exercise class','a narrow water channel','hacienda 指大型庄园。'),Q('hacienda',2,2,'The hacienda may also refer to?','the main house on such an estate','a person who repairs hair','a court verdict','该词也指庄园主宅。'),Q('hacienda',3,1,'Which setting best fits a historic hacienda?','a large rural estate in Latin America','a modern airport runway','a gym locker room','拉美乡间大型土地庄园符合 hacienda。'),Q('hacienda',4,2,'Hacienda entered English from?','Spanish','Old Norse','Chinese','该词经西班牙语进入英语。')]);
P('hack','hack 源自古英语 haccian“砍、切”，后有多种用法：粗砍、非法侵入电脑、开出租车或指平庸的雇佣写手。',C('hack.s2','网络安全','The intruder tried to hack the company’s server, but the security team detected the unauthorized access and shut it down.','入侵者试图非法侵入公司的服务器，但安全团队发现未经授权的访问并将其关闭。','The intruder tried to hack the company’s server / but the security team detected / the unauthorized access / and shut it down.','hack a server 在此指未经许可进入计算机系统；unauthorized 明确该行为未经授权。','未授权进入公司的服务器，符合 s2。'),M('The visitor was allowed to hack the company’s server by following the written access policy and using an approved account.','The visitor accessed the company’s server through the authorized login process.','按政策使用批准账号是授权访问，不是 hack 的非法入侵义。'),[Q('hack',1,1,'To hack at a branch with a tool is to?','cut it roughly or forcefully','paint it carefully','greet it politely','hack 可指粗砍。'),Q('hack',2,2,'To hack someone else’s computer system is to?','gain access without permission','use an account with explicit authorization','turn off the monitor','hack 可指非法侵入计算机系统。'),Q('hack',3,3,'In British usage, to hack as a job can mean to?','drive a taxi','teach gymnastics','work as a gynecologist','hack 也曾指开出租车。'),Q('hack',4,5,'A political hack may be?','a dull, routine writer paid to produce work','a respected volunteer scientist','a professional hairdresser','hack 可贬指平庸的职业写手。')]);
P('hacker','hacker 由 hack 加施事者后缀 -er 构成；此词条指未经许可侵入计算机系统的人。',C('hacker.s1','网络安全','The hacker stole customer records from the exposed database, and the company notified affected users after the breach was confirmed.','黑客从暴露的数据库中窃取客户记录；数据泄露确认后，公司通知了受影响的用户。','The hacker stole customer records from the exposed database / and the company notified affected users / after the breach was confirmed.','hacker 在此指非法侵入系统并窃取数据的人；after 从句说明通知的时间条件。','未经许可入侵并获取客户记录，符合 source sense。'),M('The hacker was a security tester with explicit written permission, following the company’s authorized testing plan.','The security tester had explicit written permission and followed the company’s authorized testing plan.','有书面授权并按计划测试的人不是此义中的非法入侵者。'),[Q('hacker',1,1,'A hacker in this entry is someone who?','breaks into computer systems without permission','repairs every computer with authorization','writes only printed newspapers','hacker 指侵入电脑系统的人。'),Q('hacker',2,1,'A company may investigate a hacker after?','unauthorized access to its network','a routine approved software update','a customer changes a password','未经授权访问会触发调查。'),Q('hacker',3,1,'Which role differs from a malicious hacker in this sense?','an authorized security tester following a written scope','an intruder stealing private records','a person bypassing access controls','得到许可的安全测试人员不同于非法入侵者。'),Q('hacker',4,1,'The suffix -er in hacker identifies?','a person who performs the action','a room where computers are stored','the past tense of hack','-er 构成实施动作的人。')]);
P('hackneyed','hackneyed 源自 hackney“供出租或日常使用的马”，后来形容因反复使用而失去新意的表达或想法。',C('hackneyed.s1','写作编辑','The editor removed the hackneyed opening about a “journey of a thousand miles” and asked the reporter for a more specific lead.','编辑删去了“千里之行始于足下”这一陈词滥调式开头，并请记者改用更具体的导语。','The editor removed the hackneyed opening / about a “journey of a thousand miles” / and asked the reporter / for a more specific lead.','hackneyed 修饰 opening，表示表达用得过多、缺乏新意；removed 与 asked for 显示编辑修改。','编辑认为这个表达陈旧重复，符合 s1。'),M('The phrase was hackneyed because it had never been used before and sounded completely original.','The phrase was original because it had never been used before and sounded completely fresh.','从未使用过且新颖的表达与 hackneyed 相反。'),[Q('hackneyed',1,1,'A hackneyed phrase is?','overused and lacking freshness','newly invented and original','impossible to pronounce','hackneyed 表示陈词滥调、缺乏新意。'),Q('hackneyed',2,1,'An editor may cut a hackneyed line because it?','has been repeated too often','contains a new and precise fact','is required by the law','编辑常删去过度重复的表达。'),Q('hackneyed',3,1,'Which description fits a hackneyed slogan?','a familiar cliché heard many times','a fresh idea no one has expressed','a private password','陈旧口号属于 cliché。'),Q('hackneyed',4,1,'The closest opposite of hackneyed is?','fresh and original','stale and overused','routine and predictable','fresh and original 与 hackneyed 相反。')]);
P('had better','had better 是固定情态表达，表示最好采取某行动，常带有建议或警告意味；后接动词原形。',C('had better.s1','出行提醒','You had better leave now if you want to catch the last bus, because the stop is a twenty-minute walk away.','如果你想赶上末班车，最好现在就出发，因为车站要步行二十分钟。','You had better leave now / if you want to catch the last bus / because the stop is a twenty-minute walk away.','had better 后接动词原形 leave，表示基于后果的建议；if 从句说明条件。','不立即出发可能错过末班车，因此这是建议。'),M('You had better to leave now if you want to catch the bus.','You had better leave now if you want to catch the bus.','had better 后应接动词原形，不加 to。'),[Q('had better',1,1,'“You had better call” means?','it would be wise for you to call','you were physically better in the past','you are forbidden to call','had better 表示最好、应该。'),Q('had better',2,1,'What form follows had better?','the base form of a verb','a verb with to','only a past participle','had better 后接动词原形。'),Q('had better',3,1,'“You had better wear a coat” can sound like?','advice or a warning','a simple description of clothing','a question about the past','该表达可带建议或警告意味。'),Q('had better',4,1,'Which sentence is correct?','We had better start before dark.','We had better to start before dark.','We had better started before dark.','had better 后用 start 原形。')]);
P('haft','haft 源自古英语 hæft，指刀、斧等工具的柄，也可作动词表示给工具装上柄。',C('haft.s1','工具保养','The woodworker wrapped the knife’s haft with a narrow strip of leather to make it more comfortable to hold.','木工用窄皮条缠绕刀柄，使握起来更加舒适。','The woodworker wrapped the knife’s haft / with a narrow strip of leather / to make it more comfortable / to hold.','haft 指刀柄或工具柄；to make 说明缠绕皮条的目的。','皮条缠在供手握持的部分，符合名词义 s1。'),M('He gripped the blade’s haft, the sharp metal edge, while leaving the actual handle untouched.','He gripped the blade by its haft, the handle, while keeping his hand away from the sharp edge.','haft 是柄而不是刀刃；安全握持应握住柄。'),[Q('haft',1,1,'The haft of a knife is its?','handle','sharp cutting edge','protective sheath only','haft 指刀柄。'),Q('haft',2,2,'To haft an axe means to?','fit a handle onto its head','remove the handle permanently','sharpen the blade with water','动词 haft 表示给工具装柄。'),Q('haft',3,1,'Which part would you hold when using a tool?','its haft','its cutting edge','its sharpened point','haft 是手握工具柄。'),Q('haft',4,2,'The closest synonym for haft is?','handle','blade','gullet','handle 与 haft 意义接近。')]);
P('haggle','haggle 的较早词源不确定；现代英语中指为较低价格或协议细节反复争论、讨价还价。',C('haggle.s2','合同协商','The two companies haggled over delivery dates and repair costs before signing the service agreement.','两家公司在签订服务协议前，就交货日期和维修费用反复协商。','The two companies haggled over delivery dates / and repair costs / before signing the service agreement.','haggle over + 价格或条款表示反复争论协商；before 说明发生在签约前。','双方争论合同条款后才签署，符合 s2。'),M('They haggled over the contract by agreeing immediately to every term without any discussion.','They accepted every contract term immediately without haggling.','完全没有讨论或争议地立即接受，不是 haggle。'),[Q('haggle',1,1,'To haggle with a seller is to?','argue in order to reach a lower price','pay the marked price without discussion','ask for directions to a gym','haggle 常指讨价还价。'),Q('haggle',2,2,'Companies may haggle over?','details of an agreement before accepting it','the color of a passing gust','a haircut after it is finished','haggle over 可指争论合同条款。'),Q('haggle',3,3,'A haggle can also be?','a long argument about price or terms','a type of sea bird','a medical specialty','haggle 可作名词指讨价还价的争论。'),Q('haggle',4,1,'Which scene best illustrates haggling?','a buyer and seller negotiate the price repeatedly','a customer silently pays the listed amount','a guest thanks a host','反复协商价格就是 haggle。')]);
P('hail','hail 表示冰雹的词源可追溯到古英语 hægl；其他动词义可表示招呼、公开赞扬或来自某处。',C('hail.s3','文化评论','Critics hailed the small theater as a major force in the city’s arts revival after its new productions attracted larger audiences.','新剧吸引更多观众后，评论家称赞这家小剧院是城市艺术复兴的重要力量。','Critics hailed the small theater / as a major force in the city’s arts revival / after its new productions / attracted larger audiences.','hail A as B 表示公开称赞 A 是 B；after 从句说明称赞的背景。','评论家公开赞誉剧院的重要作用，对应 s3。'),M('The critics hailed the play as a failure while praising it as a brilliant success in the same review.','The critics called the play a failure and said it was not a success.','同一判断中把作品既称为失败又称为成功，前后矛盾。'),[Q('hail',1,1,'Hail falling from a cloud consists of?','small balls of ice','warm drops of oil','pieces of dry paper','hail 作名词指冰雹。'),Q('hail',2,2,'To hail a taxi is to?','call or signal for it to stop','praise it in a review','say where it was made','hail 可指招手叫车。'),Q('hail',3,3,'Critics hailed the film as a success. They?','praised it publicly as successful','called for a taxi during the screening','reported that hail fell','hail A as B 表示公开赞扬。'),Q('hail',4,4,'“She hails from Nairobi” means she?','comes from Nairobi','is praising Nairobi','is calling a taxi in Nairobi','hail from 表示来自某地。')]);
P('hailstorm','hailstorm 由 hail 与 storm 组合而成，指持续一段时间、通常伴有强降雹的风暴。',C('hailstorm.s1','天气预警','The hailstorm damaged several greenhouse panels, so the farmer covered the remaining seedlings before the next band of weather arrived.','冰雹暴损坏了几块温室板，因此农场主在下一轮天气到来前盖好其余幼苗。','The hailstorm damaged several greenhouse panels / so the farmer covered the remaining seedlings / before the next band of weather arrived.','hailstorm 指伴有大量冰雹的风暴；so 引出防护措施。','冰雹暴击坏温室板，符合 s1。'),M('The weather report described a hailstorm even though only gentle sunshine fell and there was no hail or storm.','The weather report described a clear sunny period with no hail or storm.','无冰雹且无风暴的晴天不应称为 hailstorm。'),[Q('hailstorm',1,1,'A hailstorm is?','a period of heavy falling hail, often with stormy weather','a calm cloudless afternoon','a small group of seabirds','hailstorm 指雹暴。'),Q('hailstorm',2,1,'A hailstorm can damage?','roofs, vehicles, or crops','only a written contract','a person’s speaking habits','冰雹暴会损坏屋顶或作物。'),Q('hailstorm',3,1,'The word hailstorm combines hail with?','storm','hair','habit','hailstorm 是冰雹与风暴的复合词。'),Q('hailstorm',4,1,'People may seek shelter during a hailstorm because?','large hailstones can cause injury or damage','it guarantees perfect calm','it signals a gym class','大冰雹可能造成伤害或损坏。')]);
P('hair','hair 源自古英语 hær，可指人的头发、动物体表的毛，也可用于表示极小的距离或数量。',C('hair.s3','工程误差','The two measurements differed by a hair, so the technician repeated the test to determine whether the gap was meaningful.','两次测量只差一丝，因此技术员重复测试，以判断这个差距是否有实际意义。','The two measurements differed by a hair / so the technician repeated the test / to determine whether the gap / was meaningful.','by a hair 表示差距极小；whether 从句说明复测要确认的问题。','测量结果只差极微小的量，符合 s3。'),M('The two readings differed by a hair, meaning they were separated by several kilometers.','The two readings differed by several kilometers, not by a hair.','几公里不是极小差距，和 by a hair 的表达矛盾。'),[Q('hair',1,1,'Hair on a person’s head is?','the fine strands growing from the scalp','the skin beneath the feet','a type of mineral','hair 指头发。'),Q('hair',2,2,'An animal’s hair can mean?','the growth covering its body','a spoken greeting','a court ruling','hair 也指动物体表的毛。'),Q('hair',3,3,'By a hair means?','by a very small amount or margin','by a full kilometer','by a sudden gust','by a hair 表示只差一点点。'),Q('hair',4,1,'Which phrase uses the human-hair sense?','She brushed her hair before leaving.','The team won by a hair.','The animal has thick hair.','梳理头发是人的 hair。')]);
P('hairbreadth','hairbreadth 由 hair 与 breadth 组成，指极窄的宽度或极其微小的差距。',C('hairbreadth.s1','险情回顾','The cyclist missed the open car door by a hairbreadth and stopped immediately to avoid falling into traffic.','骑车人险些撞上敞开的车门，只差毫厘便擦碰到，随即停下以免摔进车流。','The cyclist missed the open car door by a hairbreadth / and stopped immediately / to avoid falling into traffic.','by a hairbreadth 表示只差极小距离；to avoid 说明停车目的。','骑车人与车门之间只差很窄的距离，符合 s1。'),M('The cyclist missed the door by a hairbreadth, leaving a gap of several meters between them.','The cyclist missed the door by several meters, leaving a wide gap between them.','几米宽的距离不是 hairbreadth 那样的极窄差距。'),[Q('hairbreadth',1,1,'A hairbreadth is?','a very narrow margin or tiny distance','a large area of land','a sudden flow of water','hairbreadth 指毫厘之差。'),Q('hairbreadth',2,1,'To escape by a hairbreadth is to escape?','by an extremely small margin','by several miles','without coming close to danger','by a hairbreadth 表示险些发生。'),Q('hairbreadth',3,1,'Which result is a hairbreadth victory?','winning by a fraction of a second','winning by several hours','losing by a wide margin','极微小差距获胜可称 hairbreadth。'),Q('hairbreadth',4,1,'The word is formed from hair and?','breadth','guilt','hail','hairbreadth 表示像头发宽度般的极小距离。')]);
P('haircut','haircut 由 hair 与 cut 组合而成，指剪发这一活动，也可指剪成的发型。',C('haircut.s2','造型沟通','Mina showed the barber a photograph of the short haircut she wanted, with the sides tapered and the fringe left longer.','米娜给理发师看了她想要的短发发型照片：两侧渐短，刘海留长一些。','Mina showed the barber a photograph of the short haircut she wanted / with the sides tapered / and the fringe left longer.','haircut 指剪成的发型；with 结构补充发型细节。','照片展示剪发完成后的造型，对应 s2。'),M('He showed the barber a haircut but described it as the appointment at which the barber cuts the hair.','He showed the barber a photo of the haircut style he wanted.','预约剪发是一次理发活动；照片展示的是造型。'),[Q('haircut',1,1,'A haircut can mean?','the act of having hair cut','a severe hailstorm','a person’s habitual routine','haircut 可指剪发这一活动。'),Q('haircut',2,2,'Someone showing a photo of a haircut is showing?','a style in which the hair is shaped','the act of a storm falling','a mineral sample','haircut 也指剪成的发型。'),Q('haircut',3,2,'Which question asks about haircut style?','What haircut do you want?','How long did the appointment take?','Who owns the scissors?','What haircut do you want? 常询问发型。'),Q('haircut',4,1,'A barber gives a customer?','a haircut','a habitat','a gust','理发师为顾客剪发。')]);
P('hairdo','hairdo 由 hair 与 do 组合而成，指整理、造型后的发型。',C('hairdo.s1','正式场合','For the ceremony, Jo chose a simple hairdo that kept her curls away from her face without hiding their natural shape.','为了参加仪式，乔选了一个简单发型，既让卷发不遮住脸，也没有掩盖它们自然的形状。','For the ceremony / Jo chose a simple hairdo / that kept her curls away from her face / without hiding their natural shape.','hairdo 指整理好的发型；that 从句说明造型效果。','卷发被梳理成特定样式，符合 s1。'),M('She asked the stylist for a hairdo but insisted that her hair remain completely unarranged and untouched.','She asked the stylist to leave her hair unarranged and untouched.','完全不整理头发与做好的发型相矛盾。'),[Q('hairdo',1,1,'A hairdo is?','a style in which someone’s hair is arranged','a kind of hailstorm','a medical specialty','hairdo 指发型。'),Q('hairdo',2,1,'Someone may choose a hairdo for?','a ceremony or special event','a court verdict','a weather warning','参加仪式前常会选择发型。'),Q('hairdo',3,1,'Which phrase is natural?','a simple hairdo','a gusty hairdo','a hairdo of guilt','simple hairdo 指简单发型。'),Q('hairdo',4,1,'A hairdo mainly concerns the appearance of someone’s?','hair','teeth','shoes','hairdo 与头发造型有关。')]);
P('hairdresser','hairdresser 由 hair 与 dresser 组成，指为顾客剪发、整理头发的专业人员。',C('hairdresser.s1','预约服务','The hairdresser asked how much length the customer wanted removed before washing and trimming her hair.','理发师在为顾客洗发和修剪前，先问她想剪掉多少长度。','The hairdresser asked how much length the customer wanted removed / before washing and trimming her hair.','hairdresser 指理发师；ask how much ... wanted removed 用于确认顾客需求。','该从业者为顾客洗发修剪，符合 s1。'),M('The hairdresser repaired the customer’s bicycle chain but did not cut or style anyone’s hair.','The bicycle mechanic repaired the customer’s chain but did not cut or style anyone’s hair.','修理自行车而不处理头发的人不是 hairdresser。'),[Q('hairdresser',1,1,'A hairdresser is someone who?','cuts and styles people’s hair','repairs a storm-damaged roof','studies ocean currents','hairdresser 指理发师。'),Q('hairdresser',2,1,'A customer may visit a hairdresser to?','have a haircut or hair styled','obtain a legal verdict','buy a harbor','理发师提供剪发和造型服务。'),Q('hairdresser',3,1,'Which place employs a hairdresser?','a hair salon','a weather station','a gunpowder museum','hairdresser 常在理发店或美发沙龙工作。'),Q('hairdresser',4,1,'The word hairdresser refers to?','a person','a haircut style only','a kind of hair product','-er 形式在此指从业者。')]);
P('hairlike','hairlike 由 hair 加 -like 构成，形容细长纤细、像一根毛发的。',C('hairlike.s1','自然观察','Under the microscope, the fungus produced hairlike filaments that extended from its surface into the damp wood.','显微镜下，这种真菌长出毛发般的细丝，从表面伸入潮湿木材。','Under the microscope / the fungus produced hairlike filaments / that extended from its surface / into the damp wood.','hairlike 修饰 filaments，说明它们形状细长如毛发；that 从句交代延伸方向。','细丝外形纤细、像毛发，符合 s1。'),M('The hairlike cable was as wide as a tree trunk and could not be mistaken for a thin strand.','The thick cable was as wide as a tree trunk and was not hairlike.','树干般粗的物体与毛发般细长的外形不符。'),[Q('hairlike',1,1,'A hairlike fiber is?','thin and resembling a strand of hair','wide and shaped like a brick','soft and made of chewing gum','hairlike 表示像毛发般细长。'),Q('hairlike',2,1,'A microscope might reveal hairlike structures that are?','very slender filaments','large stone blocks','circular ocean currents','hairlike 常描述纤细的丝状结构。'),Q('hairlike',3,1,'The suffix -like in hairlike means?','resembling or similar to','without any','a person who cuts','-like 表示“像……一样”。'),Q('hairlike',4,1,'Which object could be hairlike?','a fine thread-like filament','a wide stone pillar','a solid steel door','细丝状物体可形容为 hairlike。')]);
P('hairy','hairy 由 hair 加 -y 构成，可指表面多毛，也可在口语中形容危险、惊险或棘手。',C('hairy.s2','户外经历','The descent became hairy when loose stones slid under their boots, so the guide led the group back to the safer trail.','松石在他们靴下滑动时，下山路变得惊险起来，于是向导带大家返回较安全的小径。','The descent became hairy / when loose stones slid under their boots / so the guide led the group back / to the safer trail.','hairy 在口语中表示惊险或危险；so 引出转向安全路线的反应。','落石让下山过程变得危险棘手，符合 s2。'),M('The climb was hairy because it was completely safe, flat, and free of any danger.','The climb was easy because it was completely safe, flat, and free of any danger.','完全安全平坦的攀登不属于惊险危险的 hairy 情况。'),[Q('hairy',1,1,'A hairy dog has?','a lot of hair','no hair at all','a hall of residence','hairy 可指多毛的。'),Q('hairy',2,2,'A hairy situation is informally?','frightening, risky, or difficult','smooth and entirely safe','about a person’s hairstyle only','口语 hairy 可表示惊险棘手。'),Q('hairy',3,1,'Which situation sounds hairy?','crossing a narrow ledge above a steep drop','walking across a level empty room','reading a simple timetable','高处窄路带来危险，符合该口语义。'),Q('hairy',4,2,'A hairy problem is closest to a?','tricky or risky problem','perfectly simple task','soft fabric sample','hairy 可形容棘手问题。')]);
P('halcyon','halcyon 经拉丁语源自希腊语 halkyon“翠鸟”，与古代关于翠鸟平静海面的传说相关；常形容宁静幸福的往日。',C('halcyon.s1','回忆往昔','In her memoir, she recalled the halcyon summers at the lakeside cottage before the family moved to the city.','她在回忆录中追忆了搬去城市前，在湖畔小屋度过的那些宁静幸福的夏日。','In her memoir / she recalled the halcyon summers / at the lakeside cottage / before the family moved to the city.','halcyon 修饰 summers，带有回忆过去平静美好时光的意味。','被回忆为平静而幸福的往日，符合 s1。'),M('He called the peaceful, happy years halcyon while explaining that they were full of constant misery and turmoil.','He called the peaceful, happy years halcyon while explaining that they were free from constant misery and turmoil.','若岁月充满痛苦动荡，就不符合 halcyon 所指的宁静幸福。'),[Q('halcyon',1,1,'Halcyon days are remembered as?','calm, happy, and prosperous','dangerous and chaotic','completely uneventful in the future','halcyon days 指宁静幸福的日子。'),Q('halcyon',2,2,'A person recalling halcyon years is usually recalling?','pleasant, peaceful times in the past','a frightening storm tomorrow','a court hearing','该词通常修饰被怀念的美好过去。'),Q('halcyon',3,1,'In mythology, the halcyon is identified with a?','kingfisher-like bird','large land estate','kind of mineral','神话中的 halcyon 与翠鸟相关。'),Q('halcyon',4,1,'Which phrase is most natural?','the halcyon years of childhood','a halcyon gunfire','a halcyon guilt','halcyon 常形容昔日岁月。')]);
P('hale','hale 源自古英语 hāl“健康、完整”，现多见于 hale and hearty，形容年长者依然健壮；同形动词另可表示强行拖走。',C('hale.s1','健康描写','At ninety, the retired teacher was still hale and hearty, walking to the market each morning without assistance.','这位退休教师九十岁时仍然健壮，每天早晨都能独自步行去市场。','At ninety / the retired teacher was still hale and hearty / walking to the market each morning / without assistance.','hale and hearty 是固定搭配，表示健康强壮；walking 补充行动状态。','高龄仍健康、行动自如，符合形容词义 s1。'),M('The hale old sailor was described as weak, sickly, and unable to stand without help.','The frail old sailor was described as weak, sickly, and unable to stand without help.','虚弱多病与 hale 表示的健壮相反。'),[Q('hale',1,1,'A hale older person is?','vigorous and in good health','seriously ill and weak','a person who cuts hair','hale 表示健壮、健康。'),Q('hale',2,1,'The phrase “hale and hearty” describes someone?','healthy and strong','angry and guilty','quiet and asleep','固定搭配表示健康强壮。'),Q('hale',3,2,'As a verb, to hale someone away is to?','pull or drag them forcibly','praise them publicly','give them a haircut','动词 hale 可表示强行拖走。'),Q('hale',4,1,'Which detail suggests someone is hale?','they remain active and well despite old age','they cannot stand because of illness','they are caught in a hailstorm','活跃且健康体现 hale。')]);
P('half','half 源自古英语 healf，可作名词或形容词表示二等分之一，也可作副词表示部分地或指比赛的半场。',C('half.s4','体育赛事','The team conceded two goals in the first half, then changed its formation during the break.','球队在上半场丢了两球，随后在中场休息时调整阵型。','The team conceded two goals in the first half / then changed its formation / during the break.','first half 在比赛中指前半场；break 指上下半场之间的休息。','进球与中场调整表明 half 指比赛的一个时段 s4。'),M('The referee called the first half after the match had ended and all players had gone home.','The referee called the final whistle after the match had ended and all players had gone home.','比赛结束后已不存在正在进行的上半场。'),[Q('half',1,1,'Half of a cake is?','one of two equal parts','three full cakes','the entire cake plus another','half 作名词指二等分之一。'),Q('half',2,2,'A half-size portion is?','one of two equal parts in size','twice the normal size','not divided at all','half 作形容词表示一半的。'),Q('half',3,3,'“I was half asleep” means I was?','partly asleep','fully awake','sleeping for exactly two hours','half 作副词可表示部分地。'),Q('half',4,4,'In a football match, the first half is?','one of the match’s two playing periods','the final score','the stadium entrance','half 可指比赛的一段时间。')]);
P('half a dozen','half a dozen 是固定数量短语，意为六个或六位；a dozen 表示十二个。',C('half a dozen.s1','购物清单','The baker packed half a dozen rolls in a paper bag for the family’s breakfast.','面包师把六个小圆面包装进纸袋，供一家人早餐食用。','The baker packed half a dozen rolls / in a paper bag / for the family’s breakfast.','half a dozen + 复数名词表示六个；rolls 用复数形式。','纸袋里装了六个面包，符合 s1。'),M('She ordered half a dozen rolls and received exactly twelve of them.','She ordered a dozen rolls and received exactly twelve of them.','half a dozen 是六个，不是十二个。'),[Q('half a dozen',1,1,'Half a dozen means?','six','twelve','three','half a dozen 表示六个。'),Q('half a dozen',2,1,'Half a dozen eggs are?','six eggs','six pairs of eggs','twelve eggs','半打鸡蛋是六个鸡蛋。'),Q('half a dozen',3,1,'Which quantity is half a dozen?','six chairs','twelve chairs','two chairs','half a dozen 等于六。'),Q('half a dozen',4,1,'A dozen equals twelve, so half a dozen equals?','six','twenty-four','one','十二的一半是六。')]);
P('half-hearted','half-hearted 由 half 与 hearted 组成，形容缺乏热情、决心或真诚投入的。',C('half-hearted.s1','团队协作','His half-hearted apology did little to repair the relationship because he never acknowledged the specific harm he had caused.','他缺乏诚意的道歉几乎没能修复关系，因为他从未承认自己造成的具体伤害。','His half-hearted apology did little to repair the relationship / because he never acknowledged / the specific harm he had caused.','half-hearted 修饰 apology，表示不够真诚投入；because 从句说明道歉效果有限的原因。','没有承认伤害使道歉显得敷衍，符合 s1。'),M('She made a half-hearted effort by practicing every day for hours and giving the task her full commitment.','She made a wholehearted effort by practicing every day for hours and giving the task her full commitment.','全心投入、长期练习与 half-hearted 的缺乏投入相反。'),[Q('half-hearted',1,1,'A half-hearted effort is?','made with little enthusiasm or commitment','made with complete dedication','impossible to complete physically','half-hearted 表示不热心、不投入。'),Q('half-hearted',2,1,'A half-hearted apology may sound?','insincere or perfunctory','deeply thoughtful and specific','like a weather report','缺乏诚意的道歉容易显得敷衍。'),Q('half-hearted',3,1,'Which action is half-hearted?','doing the minimum while showing little interest','practicing carefully every day','taking full responsibility for a mistake','只做最低限度且不投入体现 half-hearted。'),Q('half-hearted',4,1,'The opposite of half-hearted is?','wholehearted','indifferent','casual','wholehearted 表示全心全意。')]);
P('halfway','halfway 由 half 与 way 组合而成，可指两地或一段时间的中点，也可作形容词表示只完成一半、不彻底。',C('halfway.s3','项目进度','The team was only halfway through the repairs when the replacement parts ran out, so the reopening date had to be postponed.','替换零件用完时，团队只完成了一半维修，因此不得不推迟重新开放日期。','The team was only halfway through the repairs / when the replacement parts ran out / so the reopening date / had to be postponed.','halfway through + 任务表示只完成了一部分；only 强调未到终点。','维修工作尚未完成一半以上，符合 s3 的部分完成义。'),M('They were halfway through the project after completing every task and submitting the final report.','They had finished the project after completing every task and submitting the final report.','完成所有任务并提交报告表示项目结束，不是只进行到一半。'),[Q('halfway',1,1,'Halfway between two towns is?','at an equal distance from each town','inside one town’s center only','farther from both than any other point','halfway 可指两地间等距的中点。'),Q('halfway',2,2,'Halfway through a year means?','at the middle point of the year','before the year begins','after the year has ended','halfway 可指时间过半。'),Q('halfway',3,3,'A halfway effort is?','incomplete or only partly done','finished perfectly','never started at all','halfway 可形容不彻底、只做一半。'),Q('halfway',4,1,'If a runner stops halfway through a race, the runner has?','not yet reached the finish','already won the race','never started running','halfway through 表示尚未完成。')]);
P('halite','halite 由希腊语 hals“盐”与 lithos“石”构成，指天然形成的氯化钠矿物，即岩盐。',C('halite.s1','地质标本','The geologist identified the cubic crystals as halite and explained that they formed when ancient seawater evaporated.','地质学家将立方晶体鉴定为石盐，并解释它们形成于古代海水蒸发时。','The geologist identified the cubic crystals as halite / and explained / that they formed when ancient seawater evaporated.','halite 指天然氯化钠矿物；identify A as B 表示鉴定归类。','矿物晶体由古海水蒸发形成，符合岩盐义。'),M('The sample was halite, a naturally occurring mineral made of pure liquid water.','The sample was halite, a naturally occurring mineral made mainly of sodium chloride.','halite 是氯化钠矿物，不是液态水。'),[Q('halite',1,1,'Halite is the mineral form of?','sodium chloride','calcium sulfate','cellulose nitrate','halite 是天然氯化钠。'),Q('halite',2,1,'A geologist may recognize halite by its?','often cubic crystals','hairlike fibers only','feathered wings','halite 常形成立方晶体。'),Q('halite',3,1,'Halite is also called?','rock salt','guncotton','gypsum','halite 又称岩盐。'),Q('halite',4,1,'Which process can form halite deposits?','evaporation of salty water','growth of human hair','repeated guitar practice','咸水蒸发可形成石盐沉积。')]);
P('hall','hall 源自古英语 heall，可指房屋入口处的门厅、大型集会厅、大学宿舍楼或建筑内部的走廊。',C('hall.s3','校园生活','The first-year students moved into their hall at the start of term and shared a kitchen with neighbors on the same floor.','新生在学期开始时搬进宿舍楼，并与同层邻居共用厨房。','The first-year students moved into their hall / at the start of term / and shared a kitchen / with neighbors on the same floor.','在大学语境中 hall 可指学生宿舍楼；move into 表明入住。','学生入住大学住宿楼，符合 s3。'),M('The students moved into the hall as their dormitory, although it had no rooms and was only a narrow passageway.','The students moved into the residence hall, which contained rooms where they could live.','只有狭窄过道的空间不能供学生居住。'),[Q('hall',1,1,'The hall just inside a house entrance is?','the space immediately inside the front door','a roof on top of the house','the garden behind it','hall 可指门厅。'),Q('hall',2,2,'A concert hall is?','a large room for performances or events','a small kitchen cupboard','a narrow shoe lace','hall 可指大型集会厅。'),Q('hall',3,3,'At a university, a hall may be?','a building where students live','a courtroom verdict','a type of mineral','hall 可指大学宿舍楼。'),Q('hall',4,4,'A hallway is another word for a?','passage inside a building','large concert stage','student meal','hall 也可指走廊、过道。')]);
P('hall of residence','hall of residence 是英式英语中的固定名词短语，指大学或学院为学生提供住宿的宿舍楼。',C('hall of residence.s1','大学住宿','She applied for a room in the university’s hall of residence because it was close to her classes and included shared study spaces.','她申请住进大学宿舍楼，因为那里离教室近，还设有共用自习空间。','She applied for a room in the university’s hall of residence / because it was close to her classes / and included shared study spaces.','hall of residence 指大学宿舍楼；apply for a room 表示申请住宿。','大学提供房间供学生居住，符合 s1。'),M('The university’s hall of residence was a lecture theater where no students were allowed to sleep or live.','The university’s lecture theater was used for classes, while its hall of residence provided student rooms.','不允许学生居住的讲堂不是宿舍楼。'),[Q('hall of residence',1,1,'A university hall of residence is?','a building where students live','a hall used only for court hearings','a gymnasium for competitions','hall of residence 指大学宿舍。'),Q('hall of residence',2,1,'A student in a hall of residence usually has?','a room in college accommodation','a personal seat in parliament','a house made of salt','宿舍楼为学生提供住处。'),Q('hall of residence',3,1,'Which phrase is a British term for a college dormitory?','hall of residence','hailstorm','half-hearted','该固定短语指学生宿舍楼。'),Q('hall of residence',4,1,'A student may apply to live in a?','hall of residence','hailstorm','hairbreadth','申请住进宿舍符合词义。')]);
P('hallmark','hallmark 原指在伦敦 Goldsmiths’ Hall 加盖的贵金属检验印记，后来引申为表明质量或身份的显著标志。',C('hallmark.s1','产品评价','Careful documentation is a hallmark of the research group, whose published results can be checked by other laboratories.','严谨记录是这个研究团队的显著标志，其发表的结果可供其他实验室核查。','Careful documentation is a hallmark of the research group / whose published results / can be checked / by other laboratories.','a hallmark of 表示某人或事物的典型标志；whose 从句说明团队特点。','严谨记录突出体现该团队的工作特征，符合 s1。'),M('The report called a missing serial number a hallmark of quality, even though it prevented anyone from identifying the product.','The report called a clear, verified serial number a hallmark of product identity.','缺失识别信息不能作为产品身份或质量的可靠标志。'),[Q('hallmark',1,1,'A hallmark is?','a distinctive sign of quality or identity','a sudden burst of wind','a type of hair style','hallmark 指显著标志。'),Q('hallmark',2,1,'“Attention to detail is her hallmark” means?','it is a characteristic feature of her work','she has no attention to detail','she is a jeweler only','hallmark 可比喻典型特征。'),Q('hallmark',3,1,'The original hallmark was used to?','mark precious metals as tested','label a student dormitory','measure a gulf','hallmark 原指贵金属检验印记。'),Q('hallmark',4,1,'A hallmark of reliable research is?','transparent methods and checkable results','hidden methods and missing data','a repeated cliché','可核查的结果是可靠研究的标志。')]);
P('hallowed','hallowed 是 hallow“使神圣”加过去分词后缀形成的形容词，指因宗教或传统而受到尊崇、视为神圣的。',C('hallowed.s1','历史纪念','The memorial garden is a hallowed place for the families who gather there each year to remember those lost in the war.','对于每年聚集于此、纪念战争中逝者的家属而言，这座纪念花园是受尊崇的地方。','The memorial garden is a hallowed place / for the families who gather there each year / to remember those lost in the war.','hallowed 修饰 place，表达因纪念传统而受到尊崇；to remember 说明聚集目的。','家属在此纪念逝者，使其成为受尊崇之地。'),M('The community called the memorial hallowed but treated it as an ordinary place with no respect or significance.','The community called the memorial ordinary and attached no special respect or significance to it.','毫无尊崇或特殊意义的地点不符合 hallowed。'),[Q('hallowed',1,1,'A hallowed place is?','regarded as holy or deeply respected','treated as worthless and ordinary','used only for storing tools','hallowed 表示神圣、受尊崇。'),Q('hallowed',2,1,'A tradition may make a site hallowed because?','people regard it with deep respect','nobody remembers it','it is newly painted','共同纪念和尊敬可使地点受尊崇。'),Q('hallowed',3,1,'Which phrase is natural?','hallowed ground','hallowed gunfire','hallowed haircut','hallowed 常修饰地点或传统。'),Q('hallowed',4,1,'Hallowed is closest in meaning to?','sacred','careless','halfway','sacred 表示神圣。')]);
P('hallucination','hallucination 源自拉丁语 hallucinari“在心智中游荡”，指感知到实际上不存在的事物；例句用该词描述视觉体验。',C('hallucination.s1','医疗沟通','During the fever, the patient reported a brief visual hallucination of a cat in the empty room, and the clinician recorded the symptom.','发烧期间，患者报告在空房间里短暂看见一只猫，临床人员记录了这一视觉幻觉。','During the fever / the patient reported a brief visual hallucination / of a cat in the empty room / and the clinician recorded the symptom.','hallucination 指不存在的感知体验；reported 表明这是患者描述的症状。','空房间中看到实际不存在的猫，符合视觉幻觉义。'),M('The patient reported a hallucination, but the cat was physically present and independently seen by everyone in the room.','The patient reported seeing a cat that was not actually present in the room.','所有人都能看到实际存在的猫，不符合幻觉所指的不存在感知。'),[Q('hallucination',1,1,'A hallucination is?','a perception of something that is not actually present','a verified object everyone can see','a repeated daily routine','hallucination 指不存在的感知。'),Q('hallucination',2,1,'A visual hallucination involves?','seeing something that is not there','hearing a real announcement','reading a reliable map','visual hallucination 是看到不存在的事物。'),Q('hallucination',3,1,'A clinician recording a hallucination is recording?','a reported perceptual symptom','a hairdresser’s appointment','a gymnasium schedule','幻觉可作为患者报告的感知症状记录。'),Q('hallucination',4,1,'Which detail distinguishes a hallucination from an ordinary sight?','the perceived object is not actually present','the object is clearly visible to everyone','the person is looking at a real photograph','幻觉中所感知的对象实际上不存在。')]);
P('hallway','hallway 由 hall 与 way 组合而成，指建筑物内部连接房间或入口的走廊、过道。',C('hallway.s1','家居布局','A narrow hallway connected the apartment’s front door to the bedrooms, with a coat rack mounted beside the entrance.','一条狭窄走廊把公寓前门与卧室连接起来，入口旁装着衣帽架。','A narrow hallway connected the apartment’s front door to the bedrooms / with a coat rack / mounted beside the entrance.','hallway 指建筑物内的过道；connect A to B 描述空间连接关系。','走廊连接前门和卧室，符合 s1。'),M('The hallway was a bedroom where residents slept, with a bed and wardrobe but no passage through it.','The bedroom was where residents slept, while the hallway provided passage through the apartment.','供人睡觉且没有通行功能的是卧室，不是走廊。'),[Q('hallway',1,1,'A hallway is?','a passage inside a building','a large ocean current','a type of old coin','hallway 指走廊。'),Q('hallway',2,1,'People walk through a hallway to?','move between rooms or an entrance','swim across a gulf','practice on a balance beam','走廊连接房间或入口。'),Q('hallway',3,1,'Which item is often placed in a home hallway?','a coat rack','a harbor boat','a courtroom jury','衣帽架常放在门厅走廊。'),Q('hallway',4,1,'The closest synonym for hallway is?','corridor','habitat','hallmark','corridor 表示走廊。')]);
P('halt','halt 可能经由低地德语或荷兰语的停止命令进入英语，可作动词表示停下或使停下，也可作名词表示暂停。',C('halt.s2','交通管理','A fallen tree halted traffic on the mountain road until crews cleared the branches and reopened one lane.','一棵倒下的树使山路交通停了下来，直到工作人员清除树枝并重新开放一条车道。','A fallen tree halted traffic on the mountain road / until crews cleared the branches / and reopened one lane.','halt traffic 是及物用法，表示使交通停止；until 引出恢复通行的条件。','倒树导致车辆无法继续通行，符合使停下义 s2。'),M('The fallen tree halted traffic while every car continued moving normally along the road.','The fallen tree delayed traffic while crews cleared the road.','车辆若仍正常行驶，就没有被 halted；delay 可表示受到延误。'),[Q('halt',1,1,'If a train halts, it?','stops moving','speeds up suddenly','turns into a hallway','halt 可作不及物动词表示停下。'),Q('halt',2,2,'A barrier can halt traffic by?','making vehicles stop','praising the drivers','giving them a haircut','及物 halt 表示使交通停止。'),Q('halt',3,3,'A halt is?','a stop or pause in movement or activity','a sudden large flow of liquid','a person’s hairstyle','halt 可作名词表示暂停。'),Q('halt',4,2,'Which sentence uses halt transitively?','The alarm halted the tour.','The bus halted at the corner.','There was a brief halt.','halted the tour 中有宾语，表示使活动停止。')]);
P('halve','halve 由 half 加动词后缀 -ve 形成，表示把某物分成两个相等部分，也可表示使数量减少一半。',C('halve.s2','预算调整','The clinic cut its printing budget in half to halve its printing expenses without reducing the number of patient appointments.','诊所把印刷预算削减一半，以便在不减少患者预约数量的情况下让相关开支减半。','The clinic cut its printing budget in half / to halve expenses / without reducing the number / of patient appointments.','halve expenses 表示把费用减至一半；to 引出预算调整目的。','目标是把相关支出降至原来的一半，符合 s2。'),M('The clinic halved its expenses by increasing them from ten thousand dollars to twenty thousand.','The clinic doubled its expenses by increasing them from ten thousand dollars to twenty thousand.','从一万增加到两万是翻倍，不是减半。'),[Q('halve',1,1,'To halve a loaf is to?','divide it into two equal parts','cut it into three equal parts','leave it completely untouched','halve 可指对半分。'),Q('halve',2,2,'To halve a budget is to?','reduce it to half its former amount','double it','spend none of it and erase the record','halve 也指使数量减半。'),Q('halve',3,1,'Which action halves a cake?','cutting it into two equal pieces','cutting it into four equal pieces','adding another whole cake','两等分是 halve。'),Q('halve',4,2,'If costs halve from 80 to 40, they?','fall to half the original amount','rise by 50 percent','stay exactly the same','从 80 到 40 是减半。')]);
P('ham','ham 源自古英语 hamm“腿部后侧、膝弯”，后用于腌制的猪腿肉；口语 ham 还可指业余无线电爱好者或夸张做作的演员。',C('ham.s3','业余无线电','The ham radio operator checked in with the local club and exchanged weather reports with another licensed station.','这位业余无线电爱好者向当地俱乐部报到，并与另一家持照电台交换天气信息。','The ham radio operator checked in with the local club / and exchanged weather reports / with another licensed station.','ham radio 指业余无线电；licensed station 表明在许可的业余无线电活动中交流。','操作者通过持照业余电台进行联络，符合 s3。'),M('The ham operator broadcast on a private frequency without a license and claimed this was authorized amateur radio practice.','The licensed amateur radio operator communicated through an authorized station.','无证擅自发射并非获得授权的业余无线电操作。'),[Q('ham',1,1,'Ham served at a meal is?','preserved meat from a pig’s leg','a type of ocean current','a medical condition','ham 指腌制猪腿肉。'),Q('ham',2,2,'A ham of a pig is?','its upper hind leg','its front hoof','its ear','ham 也指猪的后腿部分。'),Q('ham',3,3,'A ham radio operator is?','a licensed amateur radio enthusiast','a professional hairdresser','a person who lives in a dormitory','ham 可指业余无线电爱好者。'),Q('ham',4,4,'To ham it up on stage is to?','act in an exaggerated, theatrical way','quietly read a weather report','cook a piece of pork','ham 也可作动词表示夸张表演。')]);

})();
